import { embeddedRoboticsModules } from "./embedded-robotics";
import { foundationsElectronicsModules } from "./foundations-electronics";
import { mechanicsControlModules } from "./mechanics-control";
import type { GlossaryEntry, LearningSource } from "./types";

const MIT_DESIGN: LearningSource = { title: "MIT OpenCourseWare: Design and Manufacturing I", url: "https://ocw.mit.edu/courses/2-007-design-and-manufacturing-i-spring-2009/pages/syllabus/" };
const MIT_CIRCUITS: LearningSource = { title: "MIT OpenCourseWare: Circuits and Electronics", url: "https://ocw.mit.edu/courses/6-002-circuits-and-electronics-spring-2007/" };
const MODERN_ROBOTICS: LearningSource = { title: "Modern Robotics", url: "https://modernrobotics.northwestern.edu/" };
const MISSING_SEMESTER: LearningSource = { title: "MIT: The Missing Semester", url: "https://missing.csail.mit.edu/" };
const MICRO_PYTHON: LearningSource = { title: "MicroPython RP2 quick reference", url: "https://docs.micropython.org/en/latest/rp2/quickref.html" };
const ARDUINO_TIMING: LearningSource = { title: "Arduino: Blink Without Delay", url: "https://docs.arduino.cc/built-in-examples/digital/BlinkWithoutDelay/" };
const CONTROL_TUTORIALS: LearningSource = { title: "Control Tutorials for MATLAB and Simulink", url: "https://ctms.engin.umich.edu/CTMS/" };
const CONTINUITY_GUIDE: LearningSource = { title: "Adafruit: Multimeters — Continuity", url: "https://learn.adafruit.com/multimeters/continuity" };
const BATTERY_GUIDE: LearningSource = { title: "Adafruit: Li-Ion and LiPoly Batteries", url: "https://learn.adafruit.com/li-ion-and-lipoly-batteries" };

type AuthoredGlossaryEntry = Omit<GlossaryEntry, "relatedModules">;

const authoredGlossary: AuthoredGlossaryEntry[] = [
  { id: "unit", term: "Unit", aliases: ["unit of measure"], plain: "A named scale that gives a number physical meaning, such as metres, seconds, or volts.", technical: "A unit is an agreed reference quantity; algebra on units exposes incompatible equations and conversion errors.", example: "250 mA equals 0.250 A, so a 5 V load uses 1.25 W.", misconception: "A bare numerical result is not complete when the quantity has dimensions.", sources: [MIT_DESIGN] },
  { id: "dimension", term: "Dimension", aliases: ["physical dimension"], plain: "The kind of quantity being described, independent of the chosen unit.", technical: "Dimensions such as length, time, and current combine algebraically; a valid physical equation must be dimensionally homogeneous.", example: "Speed has dimension length/time whether written in m/s or km/h.", misconception: "Dimensional agreement is necessary but does not prove an equation is physically correct.", sources: [MIT_DESIGN] },
  { id: "estimate", term: "Estimate", aliases: ["engineering estimate", "approximation"], plain: "A deliberately simplified, bounded answer used to guide a decision before exact data exist.", technical: "An estimate states assumptions, scale, uncertainty, and validity range; it may combine models and measurements without claiming exactness.", example: "A 10 Wh source driving 2 W has an ideal runtime near 5 h before losses.", misconception: "An estimate is not a guess and extra decimal places do not make rough inputs precise.", sources: [MIT_DESIGN] },
  { id: "power", term: "Power", aliases: ["rate of energy transfer"], plain: "How quickly energy is transferred or converted.", technical: "Power is the time derivative of energy; electrical DC power is VI and mechanical rotational power is torque times angular speed.", units: "watt (W = J/s)", formula: "P = dE/dt; P = VI; P = τω", example: "A 5 V device drawing 0.4 A consumes 2 W electrically.", misconception: "Power is a rate, not stored energy or battery capacity.", sources: [MIT_CIRCUITS] },
  { id: "significant-figures", term: "Significant figures", aliases: ["significant digits"], plain: "Digits that honestly communicate the resolution supported by inputs and measurement.", technical: "Rounding should reflect uncertainty and instrument resolution, while guard digits may be retained during intermediate calculations.", example: "Inputs 5.0 V and 0.40 A justify 2.0 W, not 2.000000 W.", misconception: "Calculator output length is not evidence of measurement precision.", sources: [MIT_DESIGN] },
  { id: "equation", term: "Equation", aliases: ["equality"], plain: "A statement that two mathematical expressions represent the same value.", technical: "Equivalent transformations apply the same valid operation to both sides while preserving domain restrictions and units.", example: "From P = VI and nonzero V, divide both sides by V to obtain I = P/V.", misconception: "Terms do not magically change sign when moved; an operation was applied to both sides.", sources: [MIT_DESIGN] },
  { id: "variable", term: "Variable", aliases: ["symbolic quantity"], plain: "A named symbol whose value may change or be unknown.", technical: "A variable has a domain, meaning, units, and often a frame or time index that must remain consistent.", example: "In V = IR, I denotes current in amperes rather than an unlabeled number.", misconception: "The same letter does not guarantee the same physical meaning in different equations.", sources: [MIT_DESIGN] },
  { id: "sine", term: "Sine", aliases: ["sin"], plain: "A trigonometric ratio connecting an angle to the opposite side of a right triangle.", technical: "For angle θ, sin θ = opposite/hypotenuse and is also the y-coordinate on the unit circle.", formula: "sin θ = opposite/hypotenuse", example: "A 250 mm link at 30° rises 250 sin 30° = 125 mm.", misconception: "Sine uses the side opposite the named reference angle, not whichever side looks vertical.", sources: [MODERN_ROBOTICS] },
  { id: "cosine", term: "Cosine", aliases: ["cos"], plain: "A trigonometric ratio connecting an angle to the adjacent side of a right triangle.", technical: "For angle θ, cos θ = adjacent/hypotenuse and is the x-coordinate on the unit circle.", formula: "cos θ = adjacent/hypotenuse", example: "A 250 mm link at 30° reaches about 217 mm horizontally.", misconception: "Cosine and sine are not interchangeable; their sides depend on the declared angle.", sources: [MODERN_ROBOTICS] },
  { id: "radian", term: "Radian", aliases: ["rad"], plain: "An angle unit defined by arc length divided by radius.", technical: "One full turn is 2π radians; radian measure makes derivatives and angular equations take their standard form.", units: "radian (rad), dimensionless", formula: "θ = s/r", example: "A 90° quarter-turn equals π/2 radians.", misconception: "A calculator in radian mode will not interpret the number 60 as 60 degrees.", sources: [MODERN_ROBOTICS] },
  { id: "scalar", term: "Scalar", aliases: ["scalar quantity"], plain: "A quantity described by magnitude without a spatial direction.", technical: "A scalar is invariant under coordinate rotation, though its units and uncertainty still matter.", example: "A temperature of 22 °C is scalar; a velocity of 2 m/s east is not.", misconception: "A negative scalar may encode sense or deficit without becoming a vector.", sources: [MODERN_ROBOTICS] },
  { id: "vector", term: "Vector", aliases: ["directed quantity"], plain: "A quantity with magnitude and direction.", technical: "Vector components depend on a basis and transform between frames while geometric magnitude is preserved by pure rotation.", example: "[0.6, 0.8] m has magnitude 1.0 m in its declared frame.", misconception: "The same component pair does not describe the same direction in every coordinate frame.", sources: [MODERN_ROBOTICS] },
  { id: "reference-frame", term: "Reference frame", aliases: ["coordinate frame"], plain: "A named origin and set of axes used to describe positions and directions.", technical: "Frame transforms combine rotation and translation; free vectors use rotation, while points also depend on origin offset.", example: "A camera-forward reading must be transformed before a robot treats it as body-forward.", misconception: "Coordinates are not intrinsic properties of an object independent of a frame.", sources: [MODERN_ROBOTICS] },
  { id: "rotation-matrix", term: "Rotation matrix", aliases: ["direction-cosine matrix"], plain: "A matrix that changes vector coordinates between rotated axes.", technical: "A proper rotation matrix is orthogonal with determinant +1, so its transpose is its inverse and it preserves lengths.", formula: "R(θ) = [[cosθ, −sinθ], [sinθ, cosθ]]", example: "Rotating [1,0] by 90° produces [0,1] up to rounding.", misconception: "A rotation matrix does not translate a point or change a vector's magnitude.", sources: [MODERN_ROBOTICS] },
  { id: "component", term: "Vector component", aliases: ["coordinate component"], plain: "One signed amount of a vector along a chosen axis.", technical: "Components are projections onto basis directions and reconstruct the vector only when paired with that basis.", example: "A 1 m vector at 30° has components about 0.866 m and 0.5 m.", misconception: "A component is not an independent physical vector detached from its axis convention.", sources: [MODERN_ROBOTICS] },
  { id: "rate", term: "Rate", aliases: ["rate of change"], plain: "How much one quantity changes per unit of another, commonly per time.", technical: "An instantaneous rate is a derivative; an interval rate is a finite difference and may hide variation within the interval.", example: "Moving 1.2 m in 4 s gives an average speed of 0.3 m/s.", misconception: "An average rate does not prove the rate was constant.", sources: [MIT_DESIGN] },
  { id: "derivative", term: "Derivative", aliases: ["instantaneous slope"], plain: "The local rate at which one quantity changes with another.", technical: "The derivative is the limit of a difference quotient; sampled estimates depend on interval, noise, and numerical method.", units: "output units per input unit", formula: "dx/dt = lim(Δt→0) Δx/Δt", example: "Velocity is the time derivative of position.", misconception: "Subtracting adjacent noisy samples is only an approximation, not an exact derivative.", sources: [CONTROL_TUTORIALS] },
  { id: "integration", term: "Integration", aliases: ["accumulation", "system integration"], plain: "Depending on context, either accumulating small contributions mathematically or joining subsystems through tested interfaces.", technical: "A definite integral is a limit of weighted sums; system integration instead verifies that electrical, data, timing, mechanical, and behavioral contracts work together.", formula: "Δx = ∫v dt (mathematical scope)", example: "Multiply velocity samples by Δt to estimate travel; separately, stage sensor and motor integration from a known-good baseline.", misconception: "Raw sample addition is not numerical integration, and individually passing subsystems do not prove the integrated system works.", sources: [CONTROL_TUTORIALS, MIT_DESIGN] },
  { id: "sample-interval", term: "Sample interval", aliases: ["sampling interval", "Δt"], plain: "Elapsed time between consecutive measurements.", technical: "The interval sets temporal resolution and appears explicitly in discrete integration, differentiation, and aliasing limits.", units: "seconds (s)", example: "A 50 Hz logger has a nominal 0.020 s sample interval.", misconception: "Shorter intervals cannot remove sensor bias or guarantee evenly timed samples.", sources: [CONTROL_TUTORIALS] },
  { id: "drift", term: "Drift", aliases: ["accumulated error"], plain: "A gradual departure from the true or desired value over time.", technical: "Persistent bias integrated through a model produces unbounded or growing state error unless corrected by an external reference.", example: "A 0.01 m/s velocity bias accumulates 0.6 m of position error in 60 s.", misconception: "A smooth estimate can drift badly; visual smoothness is not accuracy.", sources: [MODERN_ROBOTICS] },
  { id: "uncertainty", term: "Measurement uncertainty", aliases: ["uncertainty"], plain: "A quantified doubt about which values could reasonably correspond to the measurand.", technical: "Uncertainty combines stated sources and coverage assumptions; it is distinct from tolerance, error, and repeatability.", example: "Report 100.2 mm ± 0.3 mm under the documented method, not simply 100.2 mm.", misconception: "Uncertainty is not a confession of bad work and does not mean every value in the interval is equally likely.", sources: [MIT_DESIGN] },
  { id: "mean", term: "Arithmetic mean", aliases: ["average"], plain: "The sum of observations divided by their count.", technical: "The sample mean estimates a distribution's central value but is sensitive to outliers and does not describe spread.", formula: "x̄ = Σxᵢ/n", example: "Measurements 9, 10, and 11 mm have mean 10 mm.", misconception: "A mean need not be an observed value or represent a multimodal dataset well.", sources: [MIT_DESIGN] },
  { id: "standard-deviation", term: "Standard deviation", aliases: ["SD", "sample spread"], plain: "A measure of how far observations typically spread around their mean.", technical: "Sample standard deviation is the square root of squared deviations divided by n−1; interpretation depends on sampling and distribution.", units: "same units as the measurement", formula: "s = √(Σ(xᵢ−x̄)²/(n−1))", example: "Repeated lengths may average 10 mm with s = 0.2 mm.", misconception: "Standard deviation is not accuracy and does not include every systematic error.", sources: [MIT_DESIGN] },
  { id: "precision", term: "Precision", aliases: ["measurement precision", "positive predictive value"], plain: "In measurement it means close agreement among repeats; in classification it means the fraction of positive predictions that are correct.", technical: "Measurement precision describes dispersion under stated conditions. Classifier precision is TP/(TP+FP), depends on threshold and evaluation prevalence, and is distinct from recall.", formula: "classifier precision = TP/(TP+FP)", example: "Tight 9.50 V readings may be precise but biased; 18 true and 3 false positives give classifier precision 18/21.", misconception: "Neither extra display digits nor high classifier precision alone establishes accuracy, recall, or generalization.", sources: [MIT_DESIGN, MODERN_ROBOTICS] },
  { id: "accuracy", term: "Accuracy", aliases: ["closeness to truth"], plain: "How close a result is to the accepted reference or true value.", technical: "Accuracy is qualitative unless tied to a defined error or uncertainty statement; it includes systematic as well as random effects.", example: "A calibrated scale averaging 100.0 g for a 100.0 g reference is accurate under that test.", misconception: "Accuracy and precision are different: repeatable readings may share the same bias.", sources: [MIT_DESIGN] },
  { id: "bias", term: "Bias", aliases: ["systematic offset"], plain: "A repeatable tendency for results to lie on one side of the target.", technical: "Statistical bias is expected estimate minus true parameter; sensor bias often appears as offset or scale error and accumulates when integrated.", example: "A thermometer reading 0.7 °C high across trials has an offset bias.", misconception: "Taking more samples reduces random noise but does not automatically remove bias.", sources: [MIT_DESIGN] },
  { id: "multimeter", term: "Multimeter", aliases: ["digital multimeter", "DMM"], plain: "An instrument for measuring quantities such as voltage, current, resistance, and continuity.", technical: "Different modes alter the meter's internal circuit; voltage is measured in parallel, current in series, and resistance on unpowered circuits.", example: "Measure a battery's terminal voltage by placing probes across its terminals.", misconception: "A meter in current mode is not placed directly across a source; that can create a short.", sources: [CONTINUITY_GUIDE] },
  { id: "continuity", term: "Continuity", aliases: ["continuity test"], plain: "Evidence that two points are joined by a sufficiently low-resistance path.", technical: "A meter sources a small test signal and beeps below an instrument-specific threshold; parallel paths can affect the result.", example: "With power removed, a cable conductor should beep end-to-end but not to adjacent conductors.", misconception: "A beep does not prove a connection will carry operating current safely.", sources: [CONTINUITY_GUIDE] },
  { id: "resolution", term: "Resolution", aliases: ["least count"], plain: "The smallest change an instrument or representation can distinguish or display.", technical: "Resolution follows display counts, quantization, range, and noise; it is separate from accuracy and repeatability.", example: "A 0.1 V display cannot directly resolve a 0.03 V change.", misconception: "Fine resolution does not guarantee correct calibration or low uncertainty.", sources: [CONTINUITY_GUIDE] },
  { id: "loading", term: "Measurement loading", aliases: ["instrument loading"], plain: "A change in the system caused by connecting the measuring instrument.", technical: "Finite input impedance, burden voltage, capacitance, mass, or thermal contact alters the measurand and must be included in the model.", example: "A low-impedance voltmeter can pull a weak sensor node downward.", misconception: "An instrument is not automatically a passive observer just because it reports a number.", sources: [MIT_CIRCUITS] },
  { id: "reference-node", term: "Reference node", aliases: ["circuit reference", "ground reference"], plain: "The circuit node assigned zero volts so other node voltages have a common meaning.", technical: "Voltage is always a difference; choosing a reference simplifies equations but does not necessarily connect it to earth.", example: "A 3.3 V rail means 3.3 V relative to the named circuit reference.", misconception: "Every point labeled ground is not automatically earth ground or mutually safe to connect.", sources: [MIT_CIRCUITS] },
  { id: "burden-voltage", term: "Burden voltage", aliases: ["ammeter burden"], plain: "The voltage drop introduced by a current-measuring instrument.", technical: "An ammeter's shunt and protection path add series impedance, potentially reducing circuit current and changing operation.", units: "volts (V)", example: "A 0.2 V burden in a 1 V sensor loop is a major disturbance.", misconception: "Current mode is not an ideal zero-ohm wire in real measurements.", sources: [MIT_CIRCUITS] },
  { id: "hypothesis", term: "Hypothesis", aliases: ["testable explanation"], plain: "A specific explanation that predicts observable outcomes.", technical: "A useful hypothesis identifies conditions and discriminating evidence that could support or contradict it.", example: "If resets come from voltage sag, the minimum rail voltage should coincide with motor startup.", misconception: "A hypothesis is not established merely because it sounds plausible.", sources: [MIT_DESIGN] },
  { id: "control", term: "Experimental control", aliases: ["control condition", "baseline"], plain: "A comparison condition kept unchanged so an intervention's effect can be distinguished.", technical: "Controls expose background drift, confounds, and measurement artifacts by preserving all relevant conditions except the tested factor.", example: "Measure the fan normally before repeating with the inlet restriction.", misconception: "A control is not necessarily a separate device or a feedback controller.", sources: [MIT_DESIGN] },
  { id: "independent-variable", term: "Independent variable", aliases: ["input factor"], plain: "The factor deliberately changed or selected during an experiment.", technical: "Its levels are controlled or categorized to estimate their effect while other influential conditions are constrained or recorded.", example: "Applied motor voltage is the independent variable in a speed test.", misconception: "The independent variable is not defined merely as whatever appears on a graph's x-axis.", sources: [MIT_DESIGN] },
  { id: "response-variable", term: "Response variable", aliases: ["dependent variable", "outcome"], plain: "The measured outcome expected to respond to an experimental change.", technical: "A response needs an operational definition, instrument, units, timing, and analysis rule chosen before observing results.", example: "Steady motor speed in rpm is a response to commanded voltage.", misconception: "A response is not automatically caused by the independent variable when confounds remain.", sources: [MIT_DESIGN] },
  { id: "confound", term: "Confound", aliases: ["confounding variable"], plain: "An uncontrolled factor that changes with the tested factor and offers another explanation.", technical: "Confounding prevents unique attribution because treatment and nuisance effects are not separately identifiable from the data.", example: "Changing motor voltage while also changing payload confounds voltage with load.", misconception: "Repeating the same confounded procedure more times does not remove the confound.", sources: [MIT_DESIGN] },
  { id: "repeatability", term: "Repeatability", aliases: ["same-condition precision"], plain: "Agreement among results repeated over a short time under the same stated conditions.", technical: "Repeatability is a precision condition with the same method, operator, instrument, location, and object; reproducibility changes conditions.", example: "Five caliper readings by one operator quantify repeatability, not universal accuracy.", misconception: "Repeatable bias can produce tightly grouped but wrong measurements.", sources: [MIT_DESIGN] },
  { id: "requirement", term: "Requirement", aliases: ["design requirement"], plain: "A testable statement of what a system must do or withstand.", technical: "A sound requirement names quantity, threshold, conditions, and verification method and remains distinct from a chosen implementation.", example: "Stop within 150 ms after command loss under the stated load.", misconception: "“Use a larger motor” is a design choice, not a performance requirement.", sources: [MIT_DESIGN] },
  { id: "constraint", term: "Constraint", aliases: ["design constraint"], plain: "A limit the design must obey rather than optimize away.", technical: "Constraints bound feasible solutions through geometry, budget, interfaces, safety, materials, or equations; CAD constraints also encode geometric relationships.", example: "The assembly must fit inside a 120 mm envelope.", misconception: "A preference is not a hard constraint unless the project declares it mandatory.", sources: [MIT_DESIGN] },
  { id: "prototype", term: "Prototype", aliases: ["test article"], plain: "A temporary implementation built to answer specific design questions.", technical: "Prototype fidelity should match the uncertainty being tested; form, function, interface, and production fidelity can differ.", example: "A cardboard linkage can test reach before a metal version tests load.", misconception: "A prototype is not automatically a rough miniature of the final product.", sources: [MIT_DESIGN] },
  { id: "verification", term: "Verification", aliases: ["requirements verification"], plain: "Checking with evidence that an implementation meets a stated requirement.", technical: "Verification uses inspection, analysis, demonstration, or test with acceptance criteria and traceable conditions.", example: "Five measured stop times below 150 ms verify only the documented test condition.", misconception: "Verification does not prove the requirement itself captures the right user need.", sources: [MIT_DESIGN] },
  { id: "traceability", term: "Traceability", aliases: ["requirements traceability", "measurement traceability"], plain: "An explicit chain connecting a claim to its requirement, decision, evidence, or reference.", technical: "In projects it links requirements to tests and revisions; in metrology it links results through calibrated references with stated uncertainties.", example: "A test record cites firmware revision, requirement ID, setup, and raw log.", misconception: "A link to a final screenshot alone is not a complete traceability chain.", sources: [MIT_DESIGN] },
  { id: "decision-matrix", term: "Decision matrix", aliases: ["weighted decision table"], plain: "A table that compares alternatives against explicit criteria.", technical: "Scores and weights structure judgment but require sensitivity checks because correlated criteria and arbitrary weights can dominate.", example: "Compare batteries on energy, peak current, mounting, charging, and cost.", misconception: "The highest total is not objective truth when assumptions or veto constraints are hidden.", sources: [MIT_DESIGN] },
  { id: "voltage", term: "Voltage", aliases: ["electric potential difference"], plain: "Energy transferred per unit charge between two points.", technical: "Voltage is a difference in electric potential and must name polarity or reference; it drives current only through a complete circuit model.", units: "volt (V = J/C)", example: "A 3.3 V pin is 3.3 joules per coulomb above its reference node.", misconception: "Voltage is not a substance stored at one isolated point.", sources: [MIT_CIRCUITS] },
  { id: "current", term: "Electric current", aliases: ["current", "amperage"], plain: "The rate at which electric charge crosses a boundary.", technical: "Conventional current is dq/dt; its value follows the complete circuit, source limits, and load rather than being independently pushed into every device.", units: "ampere (A = C/s)", formula: "I = dq/dt", example: "0.25 A for 8 s transfers 2 C.", misconception: "Current in amperes is not battery capacity in ampere-hours.", sources: [MIT_CIRCUITS] },
  { id: "resistance", term: "Resistance", aliases: ["electrical resistance"], plain: "How strongly a circuit element opposes current for a given voltage.", technical: "Static resistance is V/I at an operating point; only ohmic elements maintain a constant ratio across the relevant range.", units: "ohm (Ω = V/A)", formula: "R = V/I", example: "3 V across 1 kΩ gives 3 mA for an ideal resistor.", misconception: "Every component is not a fixed resistor, and resistance does not consume current.", sources: [MIT_CIRCUITS] },
  { id: "ohms-law", term: "Ohm's law", aliases: ["V=IR"], plain: "The relationship among voltage, current, and resistance for an ohmic element.", technical: "V = IR models a linear resistor under its stated thermal and operating conditions; it is not a universal component law.", formula: "V = IR", example: "A 330 Ω resistor carrying 4 mA drops about 1.32 V.", misconception: "Ohm's law does not make LEDs, batteries, or motors constant resistances.", sources: [MIT_CIRCUITS] },
  { id: "electrical-power", term: "Electrical power", aliases: ["electric power"], plain: "The rate at which a circuit element receives or delivers electrical energy.", technical: "Using passive sign convention, p = vi is absorbed power; resistor dissipation can be written I²R or V²/R.", units: "watt (W)", formula: "P = VI = I²R = V²/R (resistor)", example: "A 5 V load at 0.4 A absorbs 2 W.", misconception: "A component's maximum power rating is not its normal operating consumption.", sources: [MIT_CIRCUITS] },
  { id: "polarity", term: "Polarity", aliases: ["electrical orientation"], plain: "The declared positive and negative orientation of voltage, current, or a polarized component.", technical: "Polarity establishes sign conventions and safe component orientation; reversing it changes equations and can damage polarized devices.", example: "An electrolytic capacitor's negative terminal must match the lower-potential node within its rating.", misconception: "Ground symbols do not eliminate the need to check connector polarity.", sources: [MIT_CIRCUITS] },
  { id: "node", term: "Circuit node", aliases: ["electrical node"], plain: "A set of conductor points treated as sharing one electric potential.", technical: "Ideal wires join a node with zero drop; components connect between nodes and node voltages form circuit unknowns.", example: "All holes on one breadboard power strip may form one node if the strip is unbroken.", misconception: "Nearby drawing points or breadboard holes are not necessarily electrically joined.", sources: [MIT_CIRCUITS] },
  { id: "branch", term: "Circuit branch", aliases: ["branch path"], plain: "A connection between two nodes containing one or more series elements and one branch current.", technical: "Branches define graph edges for Kirchhoff analysis; all elements in a non-splitting branch share current.", example: "A resistor and LED in series between two nodes form one branch.", misconception: "A branch is not simply any visual line segment on a schematic.", sources: [MIT_CIRCUITS] },
  { id: "kcl", term: "Kirchhoff's current law", aliases: ["KCL", "node law"], plain: "Current entering a node balances current leaving it.", technical: "KCL follows charge conservation when charge accumulation at the ideal node is negligible.", formula: "ΣI = 0 at a node", example: "If 5 mA enters and 2 mA leaves one path, 3 mA must leave another.", misconception: "KCL conserves charge flow, not voltage or power at the node.", sources: [MIT_CIRCUITS] },
  { id: "kvl", term: "Kirchhoff's voltage law", aliases: ["KVL", "loop law"], plain: "Signed voltage changes sum to zero around a closed circuit loop.", technical: "KVL follows conservative electric potential in lumped circuits; rapidly changing magnetic flux requires the full induced-emf model.", formula: "ΣV = 0 around a loop", example: "A 5 V source can balance 2 V and 3 V drops.", misconception: "Voltage does not split equally unless component values and topology make it so.", sources: [MIT_CIRCUITS] },
  { id: "series", term: "Series connection", aliases: ["series circuit"], plain: "Elements connected in one unbranched path so the same current passes through them.", technical: "Ideal series resistances add; voltage division follows impedance, not merely component count.", example: "Two resistors of 1 kΩ and 2 kΩ in series total 3 kΩ.", misconception: "Components drawn next to each other are not necessarily in series if another branch joins their node.", sources: [MIT_CIRCUITS] },
  { id: "parallel", term: "Parallel connection", aliases: ["parallel circuit"], plain: "Elements connected across the same two nodes and therefore sharing voltage.", technical: "Parallel conductances add; branch currents depend on each branch impedance.", formula: "1/R_eq = Σ(1/Rᵢ)", example: "Two equal 1 kΩ resistors in parallel equal 500 Ω.", misconception: "Parallel elements share voltage, not necessarily current equally.", sources: [MIT_CIRCUITS] },
  { id: "capacitance", term: "Capacitance", aliases: ["electric capacitance"], plain: "A measure of stored charge per volt between conductors.", technical: "For an ideal capacitor q = Cv and i = C dv/dt; geometry and dielectric determine C.", units: "farad (F = C/V)", formula: "C = q/V; i = C dv/dt", example: "A 100 µF capacitor changing by 1 V changes stored charge by 100 µC.", misconception: "A capacitor does not pass steady DC current indefinitely in the ideal model.", sources: [MIT_CIRCUITS] },
  { id: "charge", term: "Electric charge", aliases: ["charge quantity"], plain: "A fundamental electrical quantity whose movement constitutes current.", technical: "Charge is conserved; current integrates to transferred charge and a capacitor stores q = Cv in the lumped model.", units: "coulomb (C = A·s)", formula: "q = ∫I dt", example: "One ampere for one second transfers one coulomb.", misconception: "Charge is not the same quantity as energy or voltage.", sources: [MIT_CIRCUITS] },
  { id: "time-constant", term: "Time constant", aliases: ["τ", "tau"], plain: "A timescale describing how quickly a first-order system approaches a new value.", technical: "After one τ a first-order rise completes about 63.2% of its total change, or a decay retains about 36.8%.", units: "seconds (s)", formula: "τ = RC for an RC circuit", example: "10 kΩ and 100 µF give τ = 1 s.", misconception: "The response is not completely finished after one time constant.", sources: [MIT_CIRCUITS] },
  { id: "transient", term: "Transient", aliases: ["transient response"], plain: "Temporary behavior while a system moves between operating conditions.", technical: "Transients arise from stored energy, dynamics, switching, and initial conditions before steady behavior dominates.", example: "Motor startup current and an RC charging curve are transients.", misconception: "A brief transient can still exceed ratings and cannot be ignored because steady state is safe.", sources: [MIT_CIRCUITS] },
  { id: "exponential", term: "Exponential response", aliases: ["exponential curve"], plain: "A change whose rate is proportional to its remaining distance from a limit.", technical: "First-order homogeneous dynamics produce e^(−t/τ); equal time intervals multiply the remaining error by a constant factor.", formula: "x(t) = x∞ + (x₀−x∞)e^(−t/τ)", example: "After 3τ, a decay retains about 5% of its initial value.", misconception: "Exponential decay approaches zero asymptotically rather than subtracting a fixed amount each second.", sources: [MIT_CIRCUITS] },
  { id: "leakage", term: "Leakage current", aliases: ["electrical leakage"], plain: "Small unintended current through a nominally insulating or off path.", technical: "Real capacitors, semiconductors, boards, and instruments have finite insulation resistance that changes held voltages over time.", units: "ampere (A)", example: "Capacitor leakage can discharge a sample-and-hold node between measurements.", misconception: "Leakage is not always negligible merely because a switch is logically off.", sources: [MIT_CIRCUITS] },
  { id: "diode", term: "Diode", aliases: ["rectifier"], plain: "A two-terminal device that conducts much more readily in one direction.", technical: "Its nonlinear current-voltage relation and reverse limits require an operating-point model rather than a universal fixed voltage drop.", example: "A series diode can block reverse battery current with a forward-voltage cost.", misconception: "Every diode does not drop exactly 0.7 V at every current and temperature.", sources: [MIT_CIRCUITS] },
  { id: "transistor", term: "Transistor", aliases: ["semiconductor switch", "amplifying device"], plain: "A controllable device used to switch or amplify electrical signals.", technical: "A small terminal signal controls a larger current or voltage subject to topology, bias, ratings, and dissipation.", example: "A transistor lets a GPIO control a motor driver input or small load without supplying load current directly.", misconception: "A transistor is not an ideal relay and still has voltage, current, thermal, and switching limits.", sources: [MIT_CIRCUITS] },
  { id: "mosfet", term: "MOSFET", aliases: ["metal-oxide-semiconductor field-effect transistor"], plain: "A voltage-controlled transistor often used as an efficient electronic switch.", technical: "Gate-source voltage controls channel resistance; safe design checks threshold versus full enhancement, charge, VDS, current, and thermal limits.", example: "A logic-level N-MOSFET can switch a low-side load when its gate is driven adequately.", misconception: "Gate-threshold voltage is not the voltage that guarantees low on-resistance.", sources: [MIT_CIRCUITS] },
  { id: "flyback-diode", term: "Flyback diode", aliases: ["freewheel diode", "catch diode"], plain: "A diode that gives inductive current a safe path when a switch turns off.", technical: "It clamps the inductive voltage by recirculating current, with polarity reverse-biased during normal energization.", example: "A diode across a relay coil limits the turn-off voltage seen by its transistor.", misconception: "The diode does not eliminate stored energy; it redirects and dissipates it over time.", sources: [MIT_CIRCUITS] },
  { id: "gate", term: "MOSFET gate", aliases: ["gate terminal"], plain: "The control terminal whose voltage establishes a MOSFET's channel state.", technical: "The insulated gate draws little DC current but has capacitance and charge that require transient drive current during switching.", example: "A gate resistor can limit ringing while a pull-down keeps a low-side MOSFET off at boot.", misconception: "Near-zero steady gate current does not mean switching the gate requires no energy or driver capability.", sources: [MIT_CIRCUITS] },
  { id: "saturation", term: "Saturation", aliases: ["actuator saturation", "transistor saturation"], plain: "A condition where increasing a command no longer produces the assumed proportional output.", technical: "In control it is an actuator limit; in a BJT it names a junction-bias region. Context must be stated because the models differ.", example: "A controller asking for 120% duty receives only the allowed 100% output.", misconception: "Saturation is not additional control effort; the excess command cannot be delivered.", sources: [MIT_CIRCUITS, CONTROL_TUTORIALS] },
  { id: "power-budget", term: "Power budget", aliases: ["load budget"], plain: "A table of expected electrical loads and the margins assigned to their shared supply.", technical: "A defensible budget separates voltage rails, steady and credible peak current, duty, conversion loss, startup, wiring drop, and thermal derating.", example: "Loads totaling 1.02 A with 30% margin require assessment at 1.326 A.", misconception: "Passing a summed current check does not validate transients, connectors, cooling, or protection.", sources: [MIT_CIRCUITS] },
  { id: "regulator", term: "Voltage regulator", aliases: ["power converter"], plain: "A circuit that maintains a target output voltage across an allowed input and load range.", technical: "Linear regulators dissipate voltage difference as heat; switching converters transfer energy through switched storage elements with finite efficiency and ripple.", example: "A 5 V regulator supplies a processor from a battery whose voltage changes during discharge.", misconception: "A regulator's headline current is not guaranteed at every input voltage, temperature, or cooling condition.", sources: [MIT_CIRCUITS] },
  { id: "efficiency", term: "Efficiency", aliases: ["conversion efficiency", "η"], plain: "The fraction of input energy or power delivered as useful output.", technical: "Efficiency is output divided by input for the same boundary and interval; the remainder becomes loss, often heat, sound, or deformation.", units: "dimensionless, often percent", formula: "η = P_out/P_in", example: "An 80% gearbox delivering 3 W needs 3.75 W mechanical input.", misconception: "Efficiency cannot exceed 100% for a passive conversion boundary, and it is not constant at every load.", sources: [MIT_DESIGN, MIT_CIRCUITS] },
  { id: "dropout-voltage", term: "Dropout voltage", aliases: ["regulator headroom"], plain: "The minimum input-to-output voltage difference a regulator needs to stay regulated.", technical: "Below dropout, output follows input and load according to the regulator topology rather than remaining at its set value.", units: "volts (V)", example: "A regulator needing 0.3 V dropout cannot hold 3.3 V from a 3.4 V input.", misconception: "Dropout is not an absolute input rating or the regulator's normal voltage loss at all conditions.", sources: [MIT_CIRCUITS] },
  { id: "thermal-margin", term: "Thermal margin", aliases: ["temperature margin"], plain: "The gap between predicted or measured temperature stress and an allowed limit.", technical: "It depends on dissipation, ambient, airflow, package thermal resistance, duration, mounting, and component derating.", example: "A driver 15 °C below its allowed junction estimate has less margin if ambient rises 20 °C.", misconception: "A current rating alone does not establish thermal margin.", sources: [MIT_CIRCUITS] },
  { id: "rail", term: "Power rail", aliases: ["supply rail"], plain: "A shared conductor or network distributing a named supply voltage.", technical: "A rail has source impedance, current limits, return paths, transients, and tolerance rather than being an ideal voltage everywhere.", example: "The 3.3 V rail powers logic while a separate motor rail carries switching current.", misconception: "Two nets with the same nominal voltage are not automatically safe to join.", sources: [MIT_CIRCUITS] },
  { id: "battery-capacity", term: "Battery capacity", aliases: ["ampere-hour capacity", "Ah"], plain: "The quantity of charge a battery can deliver under specified test conditions.", technical: "Ampere-hours integrate current over time; usable capacity varies with cutoff, rate, temperature, age, and chemistry and does not alone state energy or peak current.", units: "ampere-hour (Ah)", formula: "Q = ∫I dt", example: "2 Ah ideally represents 2 A for 1 h at the stated conditions.", misconception: "Capacity in Ah is not current capability in A and cannot be compared across voltages as energy.", sources: [BATTERY_GUIDE] },
  { id: "watt-hour", term: "Watt-hour", aliases: ["Wh", "energy capacity"], plain: "An energy unit equal to one watt sustained for one hour.", technical: "For an approximately constant nominal battery voltage, energy is estimated as voltage times ampere-hours, with discharge and conversion limits stated separately.", units: "Wh; 1 Wh = 3600 J", formula: "E ≈ V_nominal × capacity_Ah", example: "A 3.7 V, 2 Ah cell is approximately 7.4 Wh nominal.", misconception: "Watt-hours are energy, not instantaneous power or guaranteed usable output.", sources: [BATTERY_GUIDE] },
  { id: "internal-resistance", term: "Internal resistance", aliases: ["source resistance"], plain: "An equivalent resistance representing voltage loss and heating inside a real source.", technical: "Terminal voltage falls approximately by I·R_internal under a simple local model; resistance varies with charge, temperature, age, and frequency.", units: "ohm (Ω)", example: "0.2 Ω at 2 A predicts 0.4 V sag and 0.8 W internal heating.", misconception: "Internal resistance is not always constant or the only cause of battery voltage sag.", sources: [BATTERY_GUIDE] },
  { id: "cutoff", term: "Battery cutoff", aliases: ["low-voltage cutoff", "protection cutoff"], plain: "A threshold at which circuitry disconnects charge or discharge to protect the battery or system.", technical: "Cutoff behavior includes threshold, delay, hysteresis, current, temperature, and recovery conditions and may differ between charger, pack, and load.", example: "A power bank may shut off when a small load falls below its detection current.", misconception: "Cutoff is not evidence the remaining chemical energy is exactly zero.", sources: [BATTERY_GUIDE] },
  { id: "charge-controller", term: "Charge controller", aliases: ["battery charger IC"], plain: "Circuitry that applies a chemistry-specific charging profile within voltage and current limits.", technical: "Charging may include preconditioning, constant-current, constant-voltage, termination, temperature checks, and power-path behavior defined by the device.", example: "A single-cell Li-ion charger limits voltage near the chemistry's specified maximum.", misconception: "A protection board is not automatically a charger, and a charger is not universal across chemistries.", sources: [BATTERY_GUIDE] },
  { id: "protection-circuit", term: "Battery protection circuit", aliases: ["pack protection", "BMS protection"], plain: "Electronics that interrupt a battery path when selected unsafe conditions are detected.", technical: "Typical functions include overcharge, over-discharge, overcurrent, and short-circuit response, each with specified thresholds and limitations.", example: "A protected pack may disconnect during a motor surge that exceeds its current threshold.", misconception: "Protection does not make damaged cells safe or replace compatible charging and mechanical containment.", sources: [BATTERY_GUIDE] },
  { id: "logic-level", term: "Logic level", aliases: ["digital voltage level"], plain: "A voltage range interpreted as a digital low or high.", technical: "Compatibility requires sender output guarantees, receiver thresholds, supply/reference agreement, and absolute-maximum limits under load.", example: "A 3.3 V high may be valid for one 5 V input family but not another.", misconception: "“Digital” does not mean any high voltage is safe or exactly equal to the supply.", sources: [MICRO_PYTHON] },
  { id: "threshold", term: "Threshold", aliases: ["decision threshold"], plain: "A boundary used to classify a continuous value into different states.", technical: "Threshold selection trades false positives and false negatives and may include hysteresis, calibration, or an undefined region.", example: "Pixels above intensity 180 may be classified as bright features.", misconception: "A threshold is a chosen decision rule, not a natural truth guaranteed to generalize.", sources: [MODERN_ROBOTICS] },
  { id: "open-drain", term: "Open-drain output", aliases: ["open-collector output"], plain: "An output that actively pulls low but needs an external path to become high.", technical: "Multiple compliant devices can share a line because none drives high; a pull-up and bus capacitance determine high level and rise time.", example: "I²C data lines commonly use open-drain signaling with pull-ups.", misconception: "An open-drain pin does not produce a valid high by itself.", sources: [MICRO_PYTHON] },
  { id: "pull-up", term: "Pull-up resistor", aliases: ["bias resistor"], plain: "A resistor that gives a signal a default high level when nothing drives it low.", technical: "Its resistance trades low-state current against RC rise time, leakage tolerance, and noise susceptibility.", formula: "I_low ≈ V_pullup/R", example: "3.3 V through 10 kΩ draws 0.33 mA when grounded.", misconception: "A pull-up is not a power supply for loads and internal pull-ups are often loosely specified.", sources: [MICRO_PYTHON] },
  { id: "bus-capacitance", term: "Bus capacitance", aliases: ["line capacitance"], plain: "The total capacitance seen by a shared signal line.", technical: "Device inputs, traces, cables, and probes add capacitance; with a pull-up it produces a finite rise time that constrains data rate.", units: "farad, commonly pF", formula: "τ = R_pullup C_bus", example: "10 kΩ and 100 pF give a 1 µs time constant.", misconception: "A digital edge is not instantaneous merely because its logical state is binary.", sources: [MIT_CIRCUITS] },
  { id: "common-ground", term: "Common ground", aliases: ["shared reference"], plain: "A shared electrical reference that lets connected circuits interpret signal voltages consistently.", technical: "Return-current paths have impedance and topology; common reference does not imply zero noise or permission to join isolated systems.", example: "A controller and motor driver logic interface normally share a reference ground.", misconception: "Same nominal voltage without a reference connection does not guarantee valid signaling.", sources: [MIT_CIRCUITS] },
  { id: "dc-motor", term: "Brushed DC motor", aliases: ["DC motor"], plain: "A machine that converts DC electrical input into rotational torque using commutation.", technical: "A simple model combines winding resistance and inductance, torque proportional to current, and back-EMF proportional to speed.", example: "A toy-car motor draws high current at startup before back-EMF rises.", misconception: "Applied voltage does not uniquely set speed independent of load, supply, and losses.", sources: [MIT_CIRCUITS] },
  { id: "h-bridge", term: "H-bridge", aliases: ["full bridge"], plain: "Four-switch circuit that can apply either voltage polarity to a load.", technical: "Switch states provide forward, reverse, coast, or brake behavior; dead time prevents same-leg shoot-through.", example: "A motor driver reverses a brushed motor by changing which diagonal switch pair conducts.", misconception: "Arbitrary switch combinations are not safe; shoot-through can short the supply.", sources: [MIT_CIRCUITS] },
  { id: "stall-current", term: "Stall current", aliases: ["locked-rotor current"], plain: "Motor current when the shaft is not turning at a stated voltage and condition.", technical: "With back-EMF near zero, current is limited mainly by winding, driver, wiring, and source resistance; heating is severe.", units: "ampere (A)", formula: "I_stall ≈ V/R_total", example: "A 6 V path totaling 3.6 Ω predicts 1.67 A stall current.", misconception: "Free-run current is not a safe substitute for driver peak-current selection.", sources: [MIT_CIRCUITS] },
  { id: "back-emf", term: "Back electromotive force", aliases: ["back-EMF", "counter-EMF"], plain: "Voltage generated by a spinning motor that opposes the applied drive.", technical: "In a linear motor model e = k_eω; it reduces armature current as speed rises and vanishes near zero speed.", units: "volt (V)", formula: "e = k_eω", example: "Startup current is high because the stationary motor initially produces almost no back-EMF.", misconception: "Back-EMF is not an extra power source independent of motor motion.", sources: [MIT_CIRCUITS] },
  { id: "pwm", term: "Pulse-width modulation", aliases: ["PWM"], plain: "Rapidly switching an output so its on-time fraction controls an average effect.", technical: "Duty cycle, frequency, load dynamics, switching loss, and filtering determine current ripple and delivered behavior.", example: "25% duty keeps an ideal switch on for one quarter of each period.", misconception: "PWM does not create a lower steady voltage at every instant or directly command motor torque regardless of load.", sources: [MICRO_PYTHON] },
  { id: "braking", term: "Dynamic braking", aliases: ["motor braking"], plain: "Slowing a motor by providing an electrical path that opposes its motion.", technical: "Bridge braking can short motor terminals through a low-resistance path so generated current dissipates energy; regenerative braking returns energy when supported.", example: "An H-bridge brake state stops a light wheel faster than coast.", misconception: "Braking is not always equivalent to setting PWM to zero, and regenerated energy needs somewhere safe to go.", sources: [MIT_CIRCUITS] },
  { id: "force", term: "Force", aliases: ["mechanical force"], plain: "A push or pull that changes motion or loads a structure.", technical: "Force is a vector and the net external force equals mass times acceleration in an inertial frame.", units: "newton (N = kg·m/s²)", formula: "ΣF = ma", example: "A 1 kg mass weighs about 9.81 N near Earth's surface.", misconception: "Motion does not require a net force when velocity is constant.", sources: [MIT_DESIGN] },
  { id: "free-body-diagram", term: "Free-body diagram", aliases: ["FBD"], plain: "A sketch of one isolated body with every external force and moment acting on it.", technical: "Contacts are replaced by reaction components consistent with their constraints, enabling force and moment balance.", example: "A shelf FBD includes weight, support reactions, and cable tension.", misconception: "Do not include forces the isolated body exerts on other objects.", sources: [MIT_DESIGN] },
  { id: "moment", term: "Moment of a force", aliases: ["force moment", "turning moment"], plain: "The turning effect of a force about a chosen point or axis.", technical: "Moment is the cross product r×F; only perpendicular lever arm contributes, and sign follows the stated convention.", units: "newton-metre (N·m)", formula: "M = r × F", example: "10 N applied 0.2 m perpendicularly creates 2 N·m.", misconception: "Although units match torque, a moment is not energy, and lever-arm direction matters.", sources: [MIT_DESIGN] },
  { id: "equilibrium", term: "Mechanical equilibrium", aliases: ["static equilibrium"], plain: "A condition with zero net force and zero net moment.", technical: "Static equilibrium additionally has no motion; dynamic equilibrium can have constant velocity while accelerations remain zero.", formula: "ΣF = 0; ΣM = 0", example: "Two supports balance a stationary beam's weight and moments.", misconception: "Equilibrium does not mean no forces act; balanced forces can be large.", sources: [MIT_DESIGN] },
  { id: "center-of-mass", term: "Center of mass", aliases: ["COM", "mass center"], plain: "The weighted-average location of an object's mass.", technical: "Translational motion responds as if net force acts on total mass at this point; gravity may be modeled there in a uniform field.", formula: "r_cm = Σmᵢrᵢ/Σmᵢ", example: "Moving a battery changes a robot's center of mass and tipping margin.", misconception: "The center of mass need not lie inside the material of a hollow or curved object.", sources: [MIT_DESIGN] },
  { id: "torque", term: "Torque", aliases: ["shaft torque"], plain: "Rotational effort produced by a force acting through a lever arm.", technical: "Torque is r×F and rotational power is τω; available torque depends on speed, current, gearing, and thermal limits.", units: "newton-metre (N·m)", formula: "τ = rF sinθ", example: "6 N at a 32.5 mm wheel radius requires 0.195 N·m.", misconception: "High torque does not imply high power when angular speed is low; at stall mechanical power is zero.", sources: [MIT_DESIGN] },
  { id: "gear-ratio", term: "Gear ratio", aliases: ["reduction ratio"], plain: "The ratio that trades rotational speed for torque between input and output.", technical: "For reduction G = ω_in/ω_out; ideal torque multiplies by G while real output includes efficiency and load-dependent losses.", formula: "G = ω_in/ω_out; τ_out ≈ ηGτ_in", example: "A 4:1 ideal reduction gives one-quarter speed and four times torque.", misconception: "Gearing does not multiply power or guarantee the motor can operate at stall continuously.", sources: [MIT_DESIGN] },
  { id: "angular-speed", term: "Angular speed", aliases: ["rotational speed", "ω"], plain: "How quickly an angle changes with time.", technical: "Angular speed is magnitude of angular velocity; rad/s connects naturally to tangential speed and rotational power.", units: "radian per second (rad/s)", formula: "ω = dθ/dt; v = rω", example: "3000 rpm is about 314 rad/s.", misconception: "rpm and rad/s cannot be substituted without conversion.", sources: [MODERN_ROBOTICS] },
  { id: "mechanical-power", term: "Mechanical power", aliases: ["shaft power"], plain: "The rate at which a force or torque does mechanical work.", technical: "Translational power is F·v and rotational power is τ·ω using aligned components and consistent instantaneous values.", units: "watt (W)", formula: "P = F·v = τ·ω", example: "6 N at 0.5 m/s delivers 3 W.", misconception: "Maximum torque and maximum speed ratings usually occur at different operating points and cannot simply be multiplied.", sources: [MIT_DESIGN] },
  { id: "backlash", term: "Backlash", aliases: ["lost motion"], plain: "Clearance that allows an input to reverse slightly before the output follows.", technical: "Gear tooth, screw, or joint clearance creates a dead zone and direction-dependent position error, especially during reversals.", example: "A camera gear may turn several degrees before the platform reverses.", misconception: "Feedback cannot recover position information hidden inside unmeasured backlash without additional sensing or modeling.", sources: [MIT_DESIGN] },
  { id: "stress", term: "Normal stress", aliases: ["mechanical stress", "σ"], plain: "Internal force distributed over a cross-sectional area.", technical: "Average axial stress is F/A; local stress varies near holes, notches, contacts, and bending.", units: "pascal (Pa = N/m²)", formula: "σ = F/A", example: "900 N over 30 mm² gives 30 MPa average stress.", misconception: "Low average stress does not rule out a local stress concentration or another failure mode.", sources: [MIT_DESIGN] },
  { id: "strain", term: "Strain", aliases: ["engineering strain", "ε"], plain: "Deformation measured relative to an original dimension.", technical: "Axial engineering strain is change in length divided by original length and is dimensionless.", units: "dimensionless", formula: "ε = ΔL/L₀", example: "0.1 mm extension over 200 mm is 0.0005 strain.", misconception: "Strain is not force, stress, or absolute extension by itself.", sources: [MIT_DESIGN] },
  { id: "youngs-modulus", term: "Young's modulus", aliases: ["elastic modulus", "E"], plain: "A material measure of axial stiffness in its linear elastic range.", technical: "It is the slope of stress versus strain under specified conditions; geometry separately controls part stiffness.", units: "pascal (Pa)", formula: "E = σ/ε", example: "At equal geometry and load, a higher-E material extends less.", misconception: "Young's modulus measures stiffness, not yield strength or toughness.", sources: [MIT_DESIGN] },
  { id: "yield-strength", term: "Yield strength", aliases: ["yield stress"], plain: "The stress at which substantial permanent deformation begins by a specified criterion.", technical: "Yield values depend on material condition, direction, temperature, test method, and definition such as 0.2% offset.", units: "pascal, commonly MPa", example: "A 240 MPa assumed yield divided by 30 MPa stress gives safety factor 8 for that mode.", misconception: "Staying below handbook yield does not cover fatigue, buckling, creep, or stress concentrations.", sources: [MIT_DESIGN] },
  { id: "safety-factor", term: "Safety factor", aliases: ["factor of safety"], plain: "A ratio reserving strength or capacity beyond a calculated demand.", technical: "It compares a defined failure limit with a compatible calculated stress or load and must reflect uncertainty and consequence.", formula: "SF = failure limit / applied demand", example: "240 MPa yield over 30 MPa nominal stress gives SF = 8.", misconception: "A large factor cannot repair the wrong failure model or unreliable material data.", sources: [MIT_DESIGN] },
  { id: "preload", term: "Fastener preload", aliases: ["bolt preload"], plain: "Tension intentionally created in a fastener during tightening.", technical: "Preload compresses joint members and can resist separation or slip; tightening torque estimates it only indirectly through uncertain friction.", units: "newton (N)", formula: "T ≈ KFd", example: "1.2 N·m on an M4 screw with K=0.20 estimates 1.5 kN preload.", misconception: "Higher tightening torque is not always safer and can yield threads or crush the joint.", sources: [MIT_DESIGN] },
  { id: "clamping-force", term: "Clamping force", aliases: ["joint clamp load"], plain: "The compressive force holding mating joint surfaces together.", technical: "It arises from fastener preload and supports frictional shear transfer until separation or slip changes the load path.", example: "A 1500 N clamp with friction coefficient 0.25 offers roughly 375 N at one slip plane.", misconception: "Clamping force is not automatically equal to external shear load or tightening torque.", sources: [MIT_DESIGN] },
  { id: "radial-load", term: "Radial load", aliases: ["transverse bearing load"], plain: "A load acting perpendicular to a shaft's axis.", technical: "Bearing radial capacity and life depend on load magnitude, direction, speed, lubrication, fit, and combined axial load.", example: "A belt pulling sideways on a pulley places radial load on its bearings.", misconception: "A bearing that supports radial load may have little allowable thrust capacity.", sources: [MIT_DESIGN] },
  { id: "axial-load", term: "Axial load", aliases: ["thrust load"], plain: "A load acting along a shaft's axis.", technical: "Axial reaction requires a thrust-capable bearing, shoulder, or other defined load path rather than ordinary radial support alone.", example: "A lead screw can push along its axis and needs a thrust reaction.", misconception: "Two radial bearings do not automatically provide a well-defined axial constraint.", sources: [MIT_DESIGN] },
  { id: "bearing", term: "Bearing", aliases: ["rolling-element bearing"], plain: "A machine element that supports constrained relative motion while carrying load.", technical: "Selection considers radial/axial load, speed, life, fit, alignment, lubrication, sealing, and installation path.", example: "Two aligned ball bearings support a rotating wheel shaft.", misconception: "Pressing through rolling elements during installation can damage a bearing before use.", sources: [MIT_DESIGN] },
  { id: "bushing", term: "Bushing", aliases: ["plain bearing", "sleeve bearing"], plain: "A sliding bearing surface that supports a shaft without rolling elements.", technical: "Clearance, material pair, pressure-velocity limits, lubrication, wear, and alignment govern performance.", example: "A polymer sleeve can support a slow hinge shaft in a dusty mechanism.", misconception: "A bushing is not merely an undersized hole; deliberate fit and bearing material matter.", sources: [MIT_DESIGN] },
  { id: "nominal-dimension", term: "Nominal dimension", aliases: ["basic stated size"], plain: "The named target size used to identify or design a feature.", technical: "Actual permissible sizes are defined by tolerances around or relative to the nominal value.", example: "A shaft called 8 mm may be manufactured slightly below 8.000 mm.", misconception: "Nominal size is not a promise that every produced part measures exactly that value.", sources: [MIT_DESIGN] },
  { id: "tolerance", term: "Tolerance", aliases: ["permitted variation"], plain: "The allowed range of variation in a dimension or property.", technical: "Tolerance specifies conformance limits chosen for function and manufacturing; it is distinct from measured uncertainty and actual process spread.", example: "20.0 ± 0.2 mm permits 19.8 through 20.2 mm.", misconception: "Tolerance is not the same as instrument uncertainty or a guarantee of centered production.", sources: [MIT_DESIGN] },
  { id: "clearance-fit", term: "Clearance fit", aliases: ["running fit"], plain: "A fit where the hole remains larger than the shaft across allowed sizes.", technical: "Minimum clearance is smallest hole minus largest shaft; positive clearance permits assembly and motion but affects play.", formula: "C_min = H_min − S_max", example: "An 8.10 mm minimum hole with 8.00 mm maximum shaft has at least 0.10 mm diametral clearance.", misconception: "More clearance is not always better; excess play harms alignment and positioning.", sources: [MIT_DESIGN] },
  { id: "interference-fit", term: "Interference fit", aliases: ["press fit"], plain: "A fit where the shaft is larger than the hole before assembly.", technical: "Interference creates contact pressure and retention but raises assembly force and material stress; temperature and material matter.", example: "A bearing outer ring may press into a carefully toleranced housing.", misconception: "Any oversized part is not a valid press fit; excessive interference can crack or distort components.", sources: [MIT_DESIGN] },
  { id: "datum", term: "Datum", aliases: ["reference datum"], plain: "A defined reference feature from which geometry or measurements are established.", technical: "Datums create a repeatable coordinate system and constrain degrees of freedom for inspection, assembly, and CAD design.", example: "A base face and two perpendicular edges locate mounting holes.", misconception: "A datum is not merely whichever edge is convenient in one measurement.", sources: [MIT_DESIGN] },
  { id: "parameter", term: "Parameter", aliases: ["model parameter", "design parameter"], plain: "A named value that configures a design or model while variables change within it.", technical: "Parameters may be specified, measured, or estimated; identifiability and operating range determine whether fitted values are meaningful.", example: "Link length is a CAD parameter; motor gain is an identified model parameter.", misconception: "A fitted parameter is not automatically a fundamental physical constant.", sources: [MIT_DESIGN, CONTROL_TUTORIALS] },
  { id: "tolerance-stack", term: "Tolerance stack", aliases: ["stack-up analysis"], plain: "The combined effect of multiple allowed dimensional variations on an assembly result.", technical: "Worst-case sums guarantee bounds under stated independence-free limits; statistical stacks make distribution assumptions and different risk claims.", example: "Three ±0.2 mm lengths can contribute ±0.6 mm worst-case position error.", misconception: "Nominal dimensions alone cannot reveal worst-case assembly clearance.", sources: [MIT_DESIGN] },
  { id: "kerf", term: "Kerf", aliases: ["cut width"], plain: "The width of material removed by a cutting process.", technical: "Tool diameter, beam, material, speed, focus, and wear influence kerf; compensation offsets the toolpath relative to desired geometry.", units: "length, often mm", example: "A 0.2 mm laser kerf requires about 0.1 mm per-side contour compensation in a simple model.", misconception: "Kerf is not necessarily constant across every material, direction, or machine setting.", sources: [MIT_DESIGN] },
  { id: "design-intent", term: "Design intent", aliases: ["parametric intent"], plain: "The functional relationships a model is meant to preserve when dimensions change.", technical: "Constraints, datums, parameters, and feature order encode why geometry exists so edits regenerate predictably.", example: "A hole constrained concentric with a shaft remains aligned when the bracket width changes.", misconception: "A fully constrained sketch can still encode the wrong functional intent.", sources: [MIT_DESIGN] },
  { id: "kinematics", term: "Kinematics", aliases: ["motion geometry"], plain: "The study of motion without first solving the forces that cause it.", technical: "Kinematics relates position, orientation, velocity, and acceleration through mechanism geometry and time.", example: "Link lengths and joint angles determine a gripper's pose.", misconception: "A kinematically reachable pose may still be impossible because of load, collision, or actuator limits.", sources: [MODERN_ROBOTICS] },
  { id: "degree-of-freedom", term: "Degree of freedom", aliases: ["DOF"], plain: "One independent coordinate needed to describe a system's configuration.", technical: "Constraints remove degrees of freedom; mechanism mobility depends on independent constraints, not just joint count.", example: "A planar rigid body has x, y, and rotation: three DOF.", misconception: "Every joint does not necessarily add one independent usable degree of freedom.", sources: [MODERN_ROBOTICS] },
  { id: "workspace", term: "Workspace", aliases: ["reachable workspace"], plain: "The set of positions or poses a mechanism can reach.", technical: "Workspace depends on link geometry, joint limits, collisions, singularities, and whether orientation requirements are included.", example: "A two-link planar arm reaches an annular region when neither link can fold through all angles.", misconception: "Being inside a geometric envelope does not guarantee every orientation or load is achievable.", sources: [MODERN_ROBOTICS] },
  { id: "jacobian", term: "Jacobian", aliases: ["kinematic Jacobian"], plain: "A matrix relating small joint changes or rates to task-space changes or rates.", technical: "For robot kinematics, V = J(q)q̇; rank and conditioning reveal lost motion directions and force amplification.", formula: "V = J(q)q̇", example: "Near a straight two-link arm, sideways joint motion may produce little extension change.", misconception: "A Jacobian is local and configuration-dependent, not one fixed transform for the whole workspace.", sources: [MODERN_ROBOTICS] },
  { id: "singularity", term: "Kinematic singularity", aliases: ["singular configuration"], plain: "A configuration where a mechanism loses an instantaneous motion direction or requires extreme joint rates.", technical: "The Jacobian loses rank; inverse kinematics and force transmission become ill-conditioned near the singularity.", example: "A fully straight planar arm cannot instantaneously extend farther outward.", misconception: "A singularity is not merely a software crash or an unreachable point.", sources: [MODERN_ROBOTICS] },
  { id: "joint-frame", term: "Joint frame", aliases: ["joint coordinate frame"], plain: "A coordinate frame attached to a joint for describing its axis and connected links.", technical: "Consistent joint frames define transform order, positive rotation, and link geometry in a kinematic chain.", example: "A revolute joint's z-axis may define its positive rotation axis.", misconception: "Changing frame convention changes coordinates and signs even when the physical mechanism is unchanged.", sources: [MODERN_ROBOTICS] },
  { id: "static-friction", term: "Static friction", aliases: ["stiction"], plain: "Friction that prevents relative sliding up to a limit.", technical: "Its magnitude adapts as needed up to approximately μ_sN; it is not always equal to that maximum.", units: "newton (N)", formula: "|F_s| ≤ μ_sN", example: "A wheel can transmit traction without slipping while demanded force stays below the limit.", misconception: "Static friction is not automatically μ_sN in every equilibrium problem.", sources: [MIT_DESIGN] },
  { id: "kinetic-friction", term: "Kinetic friction", aliases: ["sliding friction"], plain: "Friction acting between surfaces that slide relative to each other.", technical: "A simple Coulomb model uses magnitude μ_kN opposite sliding, though real friction varies with material, speed, temperature, and lubrication.", formula: "F_k ≈ μ_kN", example: "A skidding wheel experiences sliding rather than static contact friction.", misconception: "Kinetic friction is not universally constant or always lower in every material system.", sources: [MIT_DESIGN] },
  { id: "normal-force", term: "Normal force", aliases: ["contact normal reaction"], plain: "The contact force component perpendicular to a surface.", technical: "It is determined by the full force and acceleration balance; it need not equal weight on slopes or accelerating systems.", units: "newton (N)", example: "On a level stationary table, normal force balances weight in a simple case.", misconception: "Normal force is not always mg and does not arise without contact.", sources: [MIT_DESIGN] },
  { id: "power-loss", term: "Power loss", aliases: ["dissipation", "parasitic loss"], plain: "Input power converted into an unintended form rather than useful output.", technical: "Loss depends on the chosen system boundary and may appear as heat, sound, vibration, slip, fluid drag, or electrical dissipation.", units: "watt (W)", formula: "P_loss = P_in − P_useful", example: "A gearbox taking 10 W and delivering 8 W loses 2 W.", misconception: "Lost useful power is transformed, not destroyed energy.", sources: [MIT_DESIGN] },
  { id: "signal", term: "Signal", aliases: ["measured signal"], plain: "A quantity that carries information by varying with time, space, or another variable.", technical: "A signal has units, domain, bandwidth, sampling, reference, and uncertainty; its representation is not the physical phenomenon itself.", example: "Encoder counts over time signal wheel rotation.", misconception: "Noise and signal are defined relative to the information and task, not appearance alone.", sources: [CONTROL_TUTORIALS] },
  { id: "system", term: "Dynamic system", aliases: ["plant"], plain: "A bounded part of the world whose outputs respond to inputs and internal state.", technical: "A dynamic system maps input and initial state to evolving state and output under a model and operating assumptions.", example: "A motor, load, driver, and sensor may form the plant for speed control.", misconception: "The system boundary is a modeling choice, not a naturally obvious line.", sources: [CONTROL_TUTORIALS] },
  { id: "state", term: "System state", aliases: ["dynamic state"], plain: "The smallest remembered information needed to predict future model behavior given future inputs.", technical: "State variables summarize stored energy or memory and evolve through differential or difference equations.", example: "Position and velocity form state for a simple moving mass.", misconception: "Every measured value is not necessarily a state, and state may be unmeasured.", sources: [CONTROL_TUTORIALS] },
  { id: "gain", term: "Gain", aliases: ["system gain"], plain: "How much output changes for a change in input under specified conditions.", technical: "Static gain is Δoutput/Δinput near an operating point; dynamic gain may vary with frequency and state.", units: "output units per input unit", formula: "K = Δy/Δu", example: "A local motor model may have gain 120 rpm/V.", misconception: "Gain is not necessarily dimensionless or constant across the operating range.", sources: [CONTROL_TUTORIALS] },
  { id: "step-response", term: "Step response", aliases: ["step test"], plain: "A system's output after its input changes abruptly from one constant level to another.", technical: "Rise, overshoot, settling, delay, and final gain expose dynamics within the tested amplitude and operating condition.", example: "Command fan duty from 20% to 40% and log speed versus time.", misconception: "A step response does not validate behavior for every load, amplitude, or nonlinear condition.", sources: [CONTROL_TUTORIALS] },
  { id: "feedback", term: "Feedback", aliases: ["closed-loop feedback"], plain: "Using measured output to adjust the command based on error.", technical: "Negative feedback can reject disturbances and reduce sensitivity but also creates dynamics, noise paths, and possible instability.", example: "A speed controller raises motor duty when measured speed falls below setpoint.", misconception: "Feedback cannot correct what is not sensed and does not guarantee stability.", sources: [CONTROL_TUTORIALS] },
  { id: "setpoint", term: "Setpoint", aliases: ["reference", "target"], plain: "The desired value supplied to a controller.", technical: "The reference may be filtered or trajectory-generated so demanded rate and acceleration remain feasible.", example: "A thermostat setpoint is the desired temperature, not the heater command.", misconception: "The plant output need not equal the setpoint instantly or exactly.", sources: [CONTROL_TUTORIALS] },
  { id: "error", term: "Control error", aliases: ["tracking error"], plain: "The signed difference between desired and measured output.", technical: "With convention e = r−y, sign determines corrective action; sensor bias means computed error may differ from true error.", units: "same as controlled quantity", formula: "e = r − y", example: "A 100 rpm target and 92 rpm measurement give +8 rpm error.", misconception: "Zero measured error does not prove physical truth when sensing is biased or saturated.", sources: [CONTROL_TUTORIALS] },
  { id: "pid", term: "PID controller", aliases: ["proportional-integral-derivative controller"], plain: "A feedback rule combining present, accumulated, and changing error.", technical: "u = Kp e + Ki∫e dt + Kd de/dt, implemented with sampling, filtering, limits, and anti-windup.", formula: "u = Kp e + Ki∫e dt + Kd de/dt", example: "Integral action removes a steady load offset when adequate authority remains.", misconception: "Larger gains do not always improve response and PID does not replace plant limits.", sources: [CONTROL_TUTORIALS] },
  { id: "integral-windup", term: "Integral windup", aliases: ["reset windup"], plain: "Excess accumulated controller integral while the actuator cannot deliver the requested output.", technical: "Saturation breaks the assumed loop, allowing integral state to grow and cause overshoot or slow recovery; anti-windup bounds or back-calculates it.", example: "A stalled axis accumulates positive integral even at maximum drive.", misconception: "Clipping the output alone does not prevent hidden integral state from growing.", sources: [CONTROL_TUTORIALS] },
  { id: "stability", term: "Stability", aliases: ["closed-loop stability"], plain: "The property that bounded disturbances or initial errors do not make behavior diverge uncontrollably.", technical: "Definitions include asymptotic, Lyapunov, and bounded-input bounded-output stability; each requires a specified model and operating region.", example: "A stable position loop returns near equilibrium after a small disturbance.", misconception: "A response that eventually stops in one test does not establish stability for all gains and conditions.", sources: [CONTROL_TUTORIALS] },
  { id: "damping-ratio", term: "Damping ratio", aliases: ["ζ", "zeta"], plain: "A dimensionless measure of damping relative to critical damping in a second-order model.", technical: "ζ<1 is underdamped, ζ=1 critically damped, and ζ>1 overdamped for the canonical linear model.", units: "dimensionless", example: "A low damping ratio often produces oscillatory overshoot after a step.", misconception: "Damping ratio is a model parameter, not a universal description of every nonlinear response.", sources: [CONTROL_TUTORIALS] },
  { id: "overshoot", term: "Overshoot", aliases: ["peak overshoot"], plain: "How far a response passes beyond its final or target value.", technical: "Percent overshoot is usually peak excess divided by step magnitude under a specified step-response convention.", units: "output units or percent", example: "A response peaking at 110 after a 0-to-100 step has 10% overshoot.", misconception: "Overshoot is not the same as steady-state error or measurement noise.", sources: [CONTROL_TUTORIALS] },
  { id: "settling-time", term: "Settling time", aliases: ["settle time"], plain: "Time until a response enters and remains within a stated band around its final value.", technical: "The band, reference value, disturbance, and observation window must be declared, commonly 2% or 5% for model comparisons.", units: "seconds (s)", example: "Settling to ±2% in 0.8 s means it remains there afterward in the observed interval.", misconception: "First entry into the band is not settling if the response later leaves it.", sources: [CONTROL_TUTORIALS] },
  { id: "phase-lag", term: "Phase lag", aliases: ["phase delay"], plain: "An output's periodic response occurring later in cycle than its input.", technical: "Phase is frequency-dependent; delay and stored-energy dynamics consume feedback phase margin and can promote oscillation.", units: "degree or radian", example: "A filtered sensor sinusoid may lag the physical motion more at higher frequency.", misconception: "Phase lag is not always equivalent to one fixed time delay across frequencies.", sources: [CONTROL_TUTORIALS] },
  { id: "stability-margin", term: "Stability margin", aliases: ["gain margin", "phase margin"], plain: "A measure of how much modeled loop change remains before instability.", technical: "Gain and phase margins are frequency-domain properties of an open-loop model and do not cover every nonlinearity or uncertainty.", example: "Added sensor delay can reduce phase margin even when DC gain is unchanged.", misconception: "A positive nominal margin is not a safety certification for the physical machine.", sources: [CONTROL_TUTORIALS] },
  { id: "moving-average", term: "Moving average", aliases: ["boxcar average"], plain: "A filter replacing each sample with the average of a recent window.", technical: "It reduces uncorrelated high-frequency noise but adds delay and has a frequency response with sidelobes and zeros.", formula: "y[k] = (1/N)Σx[k−i]", example: "A 5-sample average smooths ADC readings but delays a step.", misconception: "A moving average does not remove bias and does not preserve every transient.", sources: [CONTROL_TUTORIALS] },
  { id: "low-pass-filter", term: "Low-pass filter", aliases: ["smoothing filter"], plain: "A filter that passes slow changes more strongly than rapid changes.", technical: "Its cutoff and phase response trade noise reduction against delay and attenuation of real dynamics.", example: "Filtering a noisy temperature trace is reasonable because room temperature changes slowly.", misconception: "Filtered output is not automatically truer; fast real events may also be removed.", sources: [CONTROL_TUTORIALS] },
  { id: "residual", term: "Residual", aliases: ["prediction error"], plain: "The difference between an observed value and a model's prediction.", technical: "Residual structure versus time, input, or state reveals bias, missing dynamics, correlation, or changed conditions.", formula: "r[k] = y_measured[k] − y_predicted[k]", example: "Residuals growing with speed suggest the model missed a speed-dependent effect.", misconception: "Small training residuals do not establish predictive validity on new data.", sources: [CONTROL_TUTORIALS] },
  { id: "noise", term: "Measurement noise", aliases: ["random noise"], plain: "Unwanted variation that obscures the quantity of interest.", technical: "Noise is characterized by distribution, spectrum, correlation, and dependence on operating conditions; it is not synonymous with all error.", example: "ADC readings fluctuating by two counts at a steady input show short-term noise.", misconception: "A smooth trace can still be biased, and averaging correlated noise may help little.", sources: [CONTROL_TUTORIALS] },
  { id: "system-identification", term: "System identification", aliases: ["plant identification"], plain: "Estimating a model from controlled input-output data.", technical: "Model structure, excitation, parameter estimation, validation data, and operating region jointly determine useful predictive scope.", example: "Fit motor steady speed versus voltage, then test at a reserved voltage.", misconception: "A close fit does not prove the model structure is physically true.", sources: [CONTROL_TUTORIALS] },
  { id: "model-validation", term: "Model validation", aliases: ["out-of-sample validation"], plain: "Testing whether a model predicts data not used to fit it well enough for its intended decision.", technical: "Validation inspects residuals and task metrics across declared conditions and compares against alternative models or baselines.", example: "A motor model fitted at 2 V and 4 V is checked with a separate 3 V trial.", misconception: "Training fit and numerical precision are not validation.", sources: [CONTROL_TUTORIALS] },
  { id: "excitation", term: "Excitation", aliases: ["identification input"], plain: "Input variation that reveals a system's response and parameters.", technical: "Persistent excitation covers the frequencies and amplitudes needed to distinguish model effects while remaining safe and within scope.", example: "Several bounded voltage steps reveal motor gain and time constant better than one constant input.", misconception: "More violent input is not inherently more informative or safe.", sources: [CONTROL_TUTORIALS] },
  { id: "extrapolation", term: "Extrapolation", aliases: ["out-of-range prediction"], plain: "Using a model beyond the range of data that supported it.", technical: "Extrapolation depends strongly on model structure and can fail abruptly at saturation, thresholds, or changed regimes.", example: "A speed line fitted from 2–4 V should not silently predict behavior at 12 V.", misconception: "A good interpolation does not justify unlimited extrapolation.", sources: [CONTROL_TUTORIALS] },
  { id: "trajectory", term: "Trajectory", aliases: ["motion trajectory"], plain: "A time-indexed desired path including position and often velocity and acceleration.", technical: "A trajectory parameterizes motion so dynamic, actuator, collision, and timing constraints can be checked along the whole path.", example: "A camera slide command specifies where it should be at every instant of a 1.75 s move.", misconception: "A geometric path alone does not specify speed or timing.", sources: [MODERN_ROBOTICS] },
  { id: "velocity", term: "Velocity", aliases: ["linear velocity"], plain: "The rate and direction of change of position.", technical: "Velocity is a vector derivative expressed in a frame; speed is its magnitude.", units: "metre per second (m/s)", formula: "v = dx/dt", example: "A robot moving 0.5 m/s forward has signed components in its body or world frame.", misconception: "Velocity and speed are not identical when direction matters.", sources: [MODERN_ROBOTICS] },
  { id: "acceleration", term: "Acceleration", aliases: ["linear acceleration"], plain: "The rate at which velocity changes.", technical: "Acceleration is a vector and includes changes in direction even when speed stays constant.", units: "metre per second squared (m/s²)", formula: "a = dv/dt", example: "Ramping from 0 to 0.4 m/s in 0.5 s averages 0.8 m/s².", misconception: "Zero speed at an instant does not imply zero acceleration.", sources: [MODERN_ROBOTICS] },
  { id: "trapezoidal-profile", term: "Trapezoidal motion profile", aliases: ["trapezoidal velocity profile"], plain: "A move that accelerates, cruises at bounded speed, then decelerates.", technical: "It becomes triangular when travel is too short to reach the speed limit; position is the integral of its velocity segments.", example: "A 0.5 m move may use 0.5 s acceleration, 0.75 s cruise, and 0.5 s deceleration.", misconception: "Sampling an instantaneous position step more often does not create a motion profile.", sources: [MODERN_ROBOTICS] },
  { id: "tracking-error", term: "Tracking error", aliases: ["following error"], plain: "The difference between a commanded trajectory and actual motion.", technical: "Tracking error reflects plant dynamics, disturbances, sensing, delay, saturation, and controller design and is time-dependent.", example: "A slide lagging 4 mm behind its reference during acceleration has −4 mm position error under that convention.", misconception: "Small final error does not imply small peak error throughout the move.", sources: [CONTROL_TUTORIALS] },
  { id: "motion-limit", term: "Motion limit", aliases: ["kinematic limit", "rate limit"], plain: "A bound on position, speed, acceleration, jerk, torque, or another motion quantity.", technical: "Limits come from geometry, actuator capability, traction, payload, comfort, cables, and safety, and need enforcement plus fault behavior.", example: "Cap camera-pan acceleration to reduce blur even if the motor could accelerate faster.", misconception: "Software limits do not replace physical stops or validated safe-energy design.", sources: [MODERN_ROBOTICS] },
  { id: "sensor-fusion", term: "Sensor fusion", aliases: ["data fusion"], plain: "Combining complementary measurements into one estimate while retaining uncertainty and disagreement.", technical: "Fusion requires compatible quantities, frames, timestamps, calibration, noise models, and correlation assumptions.", example: "Encoders provide smooth short-term motion while camera fixes reduce long-term drift.", misconception: "Averaging more sensors does not guarantee better accuracy when errors are biased or correlated.", sources: [MODERN_ROBOTICS] },
  { id: "variance", term: "Variance", aliases: ["σ²"], plain: "A measure of squared spread around a mean.", technical: "Variance is expected squared deviation and has squared units; inverse variance weights independent unbiased estimates by modeled precision.", units: "measurement units squared", formula: "Var(X)=E[(X−μ)²]", example: "A 0.05 m standard deviation corresponds to 0.0025 m² variance.", misconception: "Variance is not standard deviation and cannot be compared without considering units and assumptions.", sources: [MODERN_ROBOTICS] },
  { id: "calibration", term: "Calibration", aliases: ["sensor calibration"], plain: "Comparing an instrument with references to characterize how readings relate to known values.", technical: "Calibration estimates offset, scale, nonlinearity, and uncertainty under stated conditions; adjustment is a separate action.", example: "Compare a distance sensor at several traceable positions and fit offset and scale.", misconception: "One-point zeroing is not complete calibration across the operating range.", sources: [MIT_DESIGN] },
  { id: "coordinate-frame", term: "Coordinate frame", aliases: ["reference frame"], plain: "A named origin and axes in which coordinates are expressed.", technical: "Fusion requires transforms and covariance handling between frames plus explicit handedness and timestamp.", example: "Rotate camera detections into the robot body frame before combining them with odometry.", misconception: "Matching units does not make coordinates compatible when axes or origins differ.", sources: [MODERN_ROBOTICS] },
  { id: "innovation", term: "Innovation", aliases: ["measurement innovation"], plain: "The difference between a new measurement and what the current estimate predicted that sensor would see.", technical: "Its covariance supports consistency checks and gating; persistent structure signals bias, timing, frame, or model problems.", formula: "ν = z − h(x̂⁻)", example: "A camera position far from predicted odometry creates a large innovation.", misconception: "A large innovation does not by itself identify which sensor or model is wrong.", sources: [MODERN_ROBOTICS] },
  { id: "correlated-error", term: "Correlated error", aliases: ["shared error"], plain: "Errors that tend to vary together rather than independently.", technical: "Shared environment, calibration, power, algorithms, or ancestry creates covariance; ignoring it makes fused uncertainty overconfident.", example: "Two cameras using the same wrong scale target share calibration error.", misconception: "Two separate sensors are not automatically statistically independent.", sources: [MODERN_ROBOTICS] },
  { id: "sample-period", term: "Sample period", aliases: ["control period", "Ts"], plain: "The intended time between successive discrete controller updates.", technical: "It shapes numerical approximation, delay, bandwidth, processor utilization, and gain interpretation; actual periods include jitter.", units: "seconds (s)", formula: "f_s = 1/T_s", example: "A 10 ms period corresponds to 100 Hz nominal updates.", misconception: "A delay call alone does not guarantee the requested period because computation also takes time.", sources: [ARDUINO_TIMING] },
  { id: "discretization", term: "Discretization", aliases: ["discrete approximation"], plain: "Turning a continuous model or controller into updates at separate times or values.", technical: "The chosen integration, hold, sampling, and quantization alter dynamics and can destabilize an otherwise stable continuous design.", example: "A controller updates integral state once every measured Δt.", misconception: "Discretization is not merely translating equation syntax into code.", sources: [CONTROL_TUTORIALS] },
  { id: "euler-method", term: "Forward Euler method", aliases: ["Euler integration"], plain: "A numerical update that projects the current slope across one time step.", technical: "x[k+1]=x[k]+Δt f(x[k],u[k]); accuracy and numerical stability depend on step size relative to dynamics.", formula: "x[k+1] = x[k] + Δt f(x[k],u[k])", example: "For dx/dt=−x/0.1 and Δt=0.02, x multiplies by 0.8.", misconception: "A stable continuous system can become numerically unstable with a coarse Euler step.", sources: [CONTROL_TUTORIALS] },
  { id: "jitter", term: "Timing jitter", aliases: ["period jitter"], plain: "Variation of actual event timing around its intended schedule.", technical: "Jitter changes sample intervals, latency, PWM edges, and numerical gains; measure timestamps rather than assuming configuration equals execution.", units: "seconds (s)", example: "A nominal 10 ms loop alternating between 8 and 13 ms has timing jitter.", misconception: "Average frequency can be correct while individual deadlines are still missed.", sources: [ARDUINO_TIMING] },
  { id: "deadline", term: "Deadline", aliases: ["timing deadline"], plain: "The latest time by which a computation or action must complete.", technical: "Real-time correctness includes value and timing; relative deadlines are compared using monotonic, rollover-safe time arithmetic.", example: "A watchdog must command zero output within 150 ms of stale input.", misconception: "Finishing eventually is not correct when the action has a deadline.", sources: [ARDUINO_TIMING] },
  { id: "quantization", term: "Quantization", aliases: ["finite-step representation"], plain: "Mapping a continuous range or fine values into discrete levels.", technical: "Quantization introduces bounded rounding error under ideal conditions and can create limit cycles, clipping, or structured error in feedback.", example: "A 12-bit ADC maps its input range into 4096 codes.", misconception: "More bits do not guarantee equivalent noise-free or accurate bits.", sources: [MICRO_PYTHON] },
  { id: "state-machine", term: "Finite-state machine", aliases: ["FSM", "state machine"], plain: "A behavior model with named states and explicit rules for changing between them.", technical: "Next state is a function of current state and inputs; outputs depend on state alone or state plus input.", example: "A robot moves from IDLE to MOVING on start and to FAULT on overcurrent.", misconception: "Every sensor value should not become a separate state; durable modes and transient data differ.", sources: [ARDUINO_TIMING] },
  { id: "transition", term: "State transition", aliases: ["transition rule"], plain: "A defined change from one state to another when a condition or event occurs.", technical: "A transition specifies source, guard/event, destination, outputs, and any entry or exit action.", example: "MOVING plus stale command transitions to FAULT with zero motor output.", misconception: "Changing an unrelated flag is not an auditable state transition when operating mode remains ambiguous.", sources: [ARDUINO_TIMING] },
  { id: "event", term: "Event", aliases: ["discrete event"], plain: "A noteworthy occurrence that may trigger program behavior.", technical: "Events may be edges, messages, timeouts, or state changes and should be queued or handled with explicit loss and ordering policy.", example: "A debounced button press is an event; its held voltage level is an input condition.", misconception: "Polling does not prevent event-oriented design, and repeated levels are not necessarily new events.", sources: [ARDUINO_TIMING] },
  { id: "blocking", term: "Blocking operation", aliases: ["blocking wait"], plain: "Work that prevents a task from handling other obligations until it finishes.", technical: "Blocking I/O or delay increases response latency and can violate scheduling deadlines unless isolated or bounded.", example: "A five-second delay prevents firmware from noticing a stop button during that interval.", misconception: "Code simplicity does not make a long block harmless in a responsive system.", sources: [ARDUINO_TIMING] },
  { id: "record", term: "Record", aliases: ["struct", "structured record"], plain: "A grouped value whose named fields describe one coherent item.", technical: "Records preserve field meaning and units; packed layouts trade readability and portability for predictable memory use.", example: "A sample record contains timestamp, ADC count, and validity flags.", misconception: "A record's memory cost is not always just the sum of field widths because alignment and runtime overhead matter.", sources: [MISSING_SEMESTER] },
  { id: "queue", term: "Queue", aliases: ["FIFO"], plain: "A collection where items normally leave in the order they arrived.", technical: "A bounded queue requires explicit full, empty, concurrency, priority, and loss behavior.", example: "Motion commands wait FIFO while an emergency stop uses a separate guaranteed path.", misconception: "Using circular storage does not require overwriting old items; storage structure and overflow policy differ.", sources: [MISSING_SEMESTER] },
  { id: "ring-buffer", term: "Ring buffer", aliases: ["circular buffer"], plain: "Fixed storage whose read or write index wraps from the end back to the start.", technical: "Modulo indexing bounds memory; full-state representation determines whether new data overwrite old data or are rejected.", formula: "next = (index + 1) mod capacity", example: "An eight-slot history retains the newest eight samples in overwrite mode.", misconception: "Ring buffers do not inherently guarantee thread safety or a particular overflow policy.", sources: [MISSING_SEMESTER] },
  { id: "capacity", term: "Buffer capacity", aliases: ["maximum capacity"], plain: "The maximum number of items a bounded structure can hold under its representation.", technical: "Capacity differs from current length and must include payload, alignment, metadata, and reserved memory constraints.", example: "10,240 bytes divided by 8 bytes per packed sample holds 1,280 samples.", misconception: "Capacity is not throughput, battery capacity, or proof that overflow cannot occur.", sources: [MISSING_SEMESTER] },
  { id: "overflow", term: "Buffer overflow", aliases: ["queue overflow"], plain: "An attempt to add data beyond available bounded storage.", technical: "Valid policies include reject, back-pressure, drop-oldest, drop-newest, or escalation, selected from loss and ordering requirements.", example: "A full command queue rejects an ordinary command and reports queue-full when loss is forbidden.", misconception: "Silent overwrite is not acceptable merely because the data structure is circular.", sources: [MISSING_SEMESTER] },
  { id: "gpio", term: "General-purpose input/output", aliases: ["GPIO", "digital pin"], plain: "A configurable microcontroller pin for observing or driving logic-level signals.", technical: "Mode, alternate function, thresholds, source/sink current, voltage limits, and boot state define safe use.", example: "Configure a button pin as input with pull-up and an LED pin as current-limited output.", misconception: "A GPIO is not a general load power terminal and must not drive a motor directly.", sources: [MICRO_PYTHON] },
  { id: "logic-threshold", term: "Logic threshold", aliases: ["input threshold"], plain: "A voltage boundary used by a digital input to recognize low or high.", technical: "Datasheets specify guaranteed low and high ranges with an undefined region; thresholds can vary with supply and temperature.", example: "A floating input may wander through the undefined region and change state.", misconception: "The switching point is not guaranteed to be exactly half the supply.", sources: [MICRO_PYTHON] },
  { id: "source-current", term: "Source current", aliases: ["current sourcing"], plain: "Current flowing out of an output pin into a load.", technical: "Per-pin and aggregate source limits, output voltage droop, package dissipation, and absolute maxima constrain operation.", example: "A high GPIO sources current through an LED and resistor to ground.", misconception: "Absolute maximum current is a damage boundary, not a recommended normal drive rating.", sources: [MICRO_PYTHON] },
  { id: "sink-current", term: "Sink current", aliases: ["current sinking"], plain: "Current flowing from a load into an output pin driven low.", technical: "Sink capability has guaranteed voltage and aggregate limits that may differ from source capability.", example: "An LED wired to 3.3 V can illuminate when the GPIO sinks current low.", misconception: "Sinking does not make current disappear; it returns through the device and supply path.", sources: [MICRO_PYTHON] },
  { id: "timer", term: "Hardware timer", aliases: ["counter/timer"], plain: "A peripheral that counts clock events to measure time or schedule actions.", technical: "Clock source, prescaler, counter width, compare registers, and rollover determine period and resolution.", example: "A compare event can update PWM without software delay loops.", misconception: "A timer's configured tick does not eliminate oscillator error or interrupt latency.", sources: [MICRO_PYTHON] },
  { id: "period", term: "Period", aliases: ["cycle time", "T"], plain: "Time required for one complete repeating cycle.", technical: "Period is the reciprocal of frequency for a periodic signal, with timing variation described separately as jitter.", units: "seconds (s)", formula: "T = 1/f", example: "A 50 Hz waveform has a 20 ms period.", misconception: "Period and on-time are different unless duty cycle is 100%.", sources: [MICRO_PYTHON] },
  { id: "frequency", term: "Frequency", aliases: ["cycle rate", "f"], plain: "The number of repeating cycles per unit time.", technical: "Frequency is reciprocal period; usable PWM frequency also depends on timer clock, count range, and required duty resolution.", units: "hertz (Hz = s⁻¹)", formula: "f = 1/T", example: "A 1 kHz PWM repeats every 1 ms.", misconception: "Higher frequency does not automatically give finer duty resolution.", sources: [MICRO_PYTHON] },
  { id: "duty-cycle", term: "Duty cycle", aliases: ["on-time fraction"], plain: "The fraction of each period that a periodic digital signal is active.", technical: "Duty D = t_on/T; average load behavior depends on amplitude, dynamics, switching topology, and filtering.", units: "dimensionless or percent", formula: "D = t_on/T", example: "2 ms high in an 8 ms period is 25% duty.", misconception: "Duty cycle is not frequency and does not guarantee proportional motor speed.", sources: [MICRO_PYTHON] },
  { id: "adc", term: "Analog-to-digital converter", aliases: ["ADC"], plain: "A circuit that represents an input voltage as a digital code.", technical: "Range, reference, resolution, sample-and-hold, source impedance, noise, linearity, and conversion timing govern the result.", example: "A 12-bit ADC ideally maps its range into codes 0 through 4095.", misconception: "Nominal bit count is not guaranteed accuracy or effective noise-free resolution.", sources: [MICRO_PYTHON] },
  { id: "reference-voltage", term: "ADC reference voltage", aliases: ["Vref"], plain: "The voltage scale against which an ADC interprets input.", technical: "Reference error and noise become gain error in converted results; input must remain within allowed range and source conditions.", units: "volt (V)", example: "With 3.3 V reference and 12 bits, one ideal code is about 0.806 mV.", misconception: "The reference is not always exactly the board's labeled supply voltage.", sources: [MICRO_PYTHON] },
  { id: "sample-rate", term: "Sample rate", aliases: ["sampling frequency", "fs"], plain: "The number of measurements taken per second.", technical: "Rate, aperture timing, analog bandwidth, and anti-alias filtering together determine which signal content can be represented.", units: "samples/s or Hz", formula: "f_s = 1/T_s", example: "100 samples/s gives a nominal 10 ms interval.", misconception: "Logging at a stated rate does not prove samples are evenly timed or alias-free.", sources: [MICRO_PYTHON] },
  { id: "aliasing", term: "Aliasing", aliases: ["sampling alias"], plain: "Fast signal variation appearing as a different slower pattern after sampling.", technical: "Frequency components above half the sampling rate fold into the sampled band unless limited before conversion.", formula: "f_Nyquist = f_s/2", example: "A rapidly spinning wheel can appear to rotate backward in sampled video.", misconception: "Software smoothing after sampling cannot reliably undo information already aliased.", sources: [MIT_CIRCUITS] },
  { id: "clipping", term: "Clipping", aliases: ["ADC saturation"], plain: "Flattening when a signal exceeds the representable or allowed range.", technical: "Samples pin at a minimum or maximum code, losing amplitude and waveform information beyond the limit.", example: "An ADC input above its reference repeatedly reports full-scale code.", misconception: "A flat maximum is not proof the physical signal became constant.", sources: [MIT_CIRCUITS] },
  { id: "interrupt", term: "Interrupt", aliases: ["hardware interrupt"], plain: "A mechanism that temporarily redirects processor execution when an event needs service.", technical: "Interrupt priority, masking, latency, nesting, shared data, and service duration affect real-time behavior.", example: "A timer interrupt marks a sample due while the main loop performs longer processing.", misconception: "Interrupts do not make code simultaneous or automatically safe from races.", sources: [MICRO_PYTHON] },
  { id: "latency", term: "Latency", aliases: ["response delay"], plain: "Elapsed time from an initiating event to the relevant response.", technical: "Latency includes sensing, queuing, computation, communication, scheduling, and actuation; distributions and worst credible values matter.", units: "seconds (s)", example: "Command-to-zero latency includes timeout detection plus output update.", misconception: "High throughput does not imply low latency.", sources: [ARDUINO_TIMING] },
  { id: "isr", term: "Interrupt service routine", aliases: ["ISR", "interrupt handler"], plain: "Code run in response to an interrupt.", technical: "An ISR should bound execution, acknowledge its source, avoid unsafe blocking, and coordinate shared state with appropriate atomicity.", example: "A timer ISR increments a counter while main code processes accumulated ticks.", misconception: "Complex logging inside an ISR can increase latency and lose other events.", sources: [MICRO_PYTHON] },
  { id: "critical-section", term: "Critical section", aliases: ["atomic region"], plain: "Code that accesses shared state and must not be interleaved with conflicting access.", technical: "Protection may disable interrupts briefly, use locks, or use atomic operations; duration must remain bounded.", example: "Reading a multi-byte counter updated by an ISR may require a protected snapshot.", misconception: "Marking data volatile does not make a multi-step update atomic.", sources: [MICRO_PYTHON] },
  { id: "utilization", term: "Processor utilization", aliases: ["CPU utilization"], plain: "The fraction of available processor time demanded by work.", technical: "For periodic tasks, nominal utilization sums execution time divided by period, but schedulability also depends on deadlines, blocking, and priority.", units: "dimensionless or percent", formula: "U = Σ(Cᵢ/Tᵢ)", example: "2 ms of work every 10 ms uses 20% nominal utilization.", misconception: "Average utilization below 100% does not guarantee every deadline is met.", sources: [ARDUINO_TIMING] },
  { id: "race-condition", term: "Race condition", aliases: ["data race", "timing race"], plain: "A bug where the outcome depends on uncontrolled ordering of concurrent events.", technical: "Non-atomic shared-state access can lose updates or observe inconsistent combinations; synchronization must protect the invariant.", example: "Main code clears a flag just as an ISR sets it, losing an event.", misconception: "A race may disappear under logging because timing changed, not because the code became correct.", sources: [MISSING_SEMESTER] },
  { id: "protocol", term: "Communication protocol", aliases: ["wire protocol"], plain: "An agreed contract for exchanging messages.", technical: "It defines physical assumptions, framing, fields, units, ordering, timing, error detection, retries, and version behavior.", example: "A sensor packet specifies header, length, payload units, checksum, and timeout.", misconception: "Matching connector shape or baud rate alone does not establish protocol compatibility.", sources: [MICRO_PYTHON] },
  { id: "frame", term: "Data frame", aliases: ["message frame", "packet frame"], plain: "A bounded group of transmitted symbols interpreted as one communication unit.", technical: "Framing uses length, delimiters, fixed fields, timing, or encoding and must recover after corruption or byte loss.", example: "A frame contains type, length, payload, and checksum.", misconception: "This communication frame is different from a spatial coordinate frame.", sources: [MICRO_PYTHON] },
  { id: "baud-rate", term: "Baud rate", aliases: ["symbol rate"], plain: "The number of transmitted symbols per second.", technical: "Baud equals bit rate only when each symbol carries one bit; asynchronous UART peers also need matching framing and tolerable clock error.", units: "baud (symbols/s)", example: "A binary UART configured at 115200 baud nominally sends 115200 symbols/s.", misconception: "Baud is not universally identical to bits per second.", sources: [MICRO_PYTHON] },
  { id: "checksum", term: "Checksum", aliases: ["error-detecting code"], plain: "A value computed from message data to detect likely corruption.", technical: "Coverage depends on algorithm and error model; checksums detect but generally do not correct errors or authenticate senders.", example: "A receiver recomputes a CRC and rejects a frame whose value differs.", misconception: "A valid checksum does not prove data are fresh, authentic, or semantically plausible.", sources: [MICRO_PYTHON] },
  { id: "timeout", term: "Timeout", aliases: ["communication timeout"], plain: "A declared maximum wait before treating an expected event as late or absent.", technical: "Timeout selection accounts for normal latency and jitter while bounding stale behavior; recovery and evidence must be explicit.", example: "Stop a motor if no fresh command arrives for 150 ms.", misconception: "A timeout identifies lateness, not the root cause of the missing event.", sources: [ARDUINO_TIMING] },
  { id: "idempotent", term: "Idempotent operation", aliases: ["retry-safe operation"], plain: "An operation whose repeated application has the same intended effect as applying it once.", technical: "Idempotency simplifies retries when acknowledgments can be lost; sequence numbers may still be needed for ordering and freshness.", example: "“Set output to zero” is idempotent; “increase output by one” is not.", misconception: "Idempotent does not mean side-effect free or immune to stale commands.", sources: [MISSING_SEMESTER] },
  { id: "reproducibility", term: "Reproducibility", aliases: ["reproducible result"], plain: "The ability to obtain a consistent result using documented methods under changed people, equipment, or setting.", technical: "Reproducibility needs versions, conditions, raw evidence, uncertainty, and deviations; repeatability is the narrower same-condition case.", example: "Another builder follows the packet and measures a comparable watchdog response.", misconception: "A polished screenshot or source archive alone does not make a result reproducible.", sources: [MISSING_SEMESTER] },
  { id: "assertion", term: "Assertion", aliases: ["runtime invariant check"], plain: "A check that a condition believed necessary is currently true.", technical: "Assertions expose violated programmer assumptions near their source and should record enough context without replacing external input validation.", example: "Assert that a ring-buffer index remains below capacity.", misconception: "Assertions are not a recovery strategy and may be disabled in some production configurations.", sources: [MISSING_SEMESTER] },
  { id: "structured-log", term: "Structured log", aliases: ["machine-readable log"], plain: "A log whose named fields follow a consistent schema rather than only prose.", technical: "Timestamps, event names, units, IDs, state, and version permit filtering and correlation across subsystems.", example: "Log {time_ms, old_state, event, new_state, voltage_V} for each transition.", misconception: "More log volume is not better when fields lack units, timing, or relevance.", sources: [MISSING_SEMESTER] },
  { id: "fault-isolation", term: "Fault isolation", aliases: ["diagnostic isolation"], plain: "Narrowing a symptom to the subsystem, interface, or cause that can explain it.", technical: "Change one condition from a known-good baseline and use discriminating measurements rather than replacing parts randomly.", example: "Measure rail sag and reset cause while adding motor load one stage at a time.", misconception: "The most visible failing component is not necessarily the source of the fault.", sources: [MISSING_SEMESTER] },
  { id: "reset-cause", term: "Reset cause", aliases: ["reset reason"], plain: "Recorded evidence of why a processor restarted.", technical: "Hardware status may distinguish power-on, watchdog, brownout, software, or external reset, though flags and retention behavior are device-specific.", example: "A brownout flag supports a supply-sag hypothesis during motor startup.", misconception: "A reboot symptom alone does not prove software crashed.", sources: [MICRO_PYTHON] },
  { id: "heisenbug", term: "Heisenbug", aliases: ["observer-sensitive bug"], plain: "A defect that changes or disappears when attempts to observe it alter timing or state.", technical: "Logging, breakpoints, probes, optimization, and memory layout can perturb races, electrical loading, and deadlines.", example: "Adding serial prints hides a missed-deadline race by slowing both tasks.", misconception: "Intermittence does not make the bug imaginary; observation itself may be an input.", sources: [MISSING_SEMESTER] },
  { id: "robot-architecture", term: "Robot architecture", aliases: ["robot software architecture"], plain: "The division of robot responsibilities into components and explicit interfaces.", technical: "Architecture assigns sensing, estimation, planning, control, supervision, timing, ownership, and fault containment across boundaries.", example: "A motion controller enforces local freshness even if a high-level planner stalls.", misconception: "Architecture is not merely a box diagram; runtime contracts and failure behavior matter.", sources: [MODERN_ROBOTICS] },
  { id: "interface", term: "Interface", aliases: ["system boundary"], plain: "A defined boundary through which components exchange power, data, forces, or services.", technical: "An interface specifies connector or call, direction, units, timing, valid range, ownership, startup, and faults.", example: "A motor command interface names percent duty, sign, update rate, and stale-command response.", misconception: "Two components are not compatible merely because their plugs or function names match.", sources: [MIT_DESIGN] },
  { id: "watchdog", term: "Watchdog", aliases: ["watchdog timer"], plain: "An independent mechanism that triggers a bounded response when expected activity stops.", technical: "A watchdog must be refreshed only by demonstrated healthy progress and needs a defined reset, safe-output, evidence, and recovery path.", example: "The motor controller commands zero after 150 ms without a fresh command.", misconception: "Refreshing a watchdog from an unconditional timer proves only that the timer still runs.", sources: [MICRO_PYTHON] },
  { id: "command-freshness", term: "Command freshness", aliases: ["command age"], plain: "How recently an actuator command was produced or validated.", technical: "Freshness uses monotonic timestamps, sequence numbers, and expiry policy to prevent stale but syntactically valid commands from persisting.", units: "seconds (s)", example: "Reject a drive command whose age exceeds 150 ms.", misconception: "A valid checksum does not make an old command fresh.", sources: [ARDUINO_TIMING] },
  { id: "supervisor", term: "Supervisor", aliases: ["supervisory controller"], plain: "A component that monitors subsystem health and coordinates operating or fault modes.", technical: "It evaluates cross-system conditions and requests degraded or safe states while local components retain immediate safety limits.", example: "A supervisor stops planning and requests zero motion after localization disagreement persists.", misconception: "A central supervisor should not be the only layer capable of bounding actuator energy.", sources: [MODERN_ROBOTICS] },
  { id: "kinematic-chain", term: "Kinematic chain", aliases: ["linkage chain"], plain: "An ordered set of rigid links connected by joints.", technical: "Successive joint transforms map configurations to end-effector pose; open and closed chains have different constraint structure.", example: "Base, shoulder link, elbow link, and camera form an open chain.", misconception: "Listing joints without their axes and transform order does not define a chain.", sources: [MODERN_ROBOTICS] },
  { id: "forward-kinematics", term: "Forward kinematics", aliases: ["FK"], plain: "Computing an end pose from known joint values and link geometry.", technical: "Ordered homogeneous transforms compose from base to tool; the result is generally unique for a fully specified chain configuration.", example: "Two link angles determine a planar gripper's x, y, and orientation.", misconception: "Forward kinematics does not solve required joint torques or collision safety.", sources: [MODERN_ROBOTICS] },
  { id: "inverse-kinematics", term: "Inverse kinematics", aliases: ["IK"], plain: "Finding joint values that produce a desired end pose.", technical: "IK can have zero, one, many, or continuous solutions subject to joint limits, singularities, and numerical convergence.", example: "A planar arm may reach one point with elbow-up or elbow-down solutions.", misconception: "A numerical IK answer is not automatically collision-free, load-capable, or within limits.", sources: [MODERN_ROBOTICS] },
  { id: "pose", term: "Pose", aliases: ["position and orientation"], plain: "An object's location and orientation relative to a named frame.", technical: "A rigid-body pose is an element of SE(3), commonly represented by rotation and translation with conventions stated.", example: "A camera pose includes its xyz position and which direction its optical axis faces.", misconception: "Position alone does not fully specify a rigid object's pose.", sources: [MODERN_ROBOTICS] },
  { id: "homogeneous-transform", term: "Homogeneous transform", aliases: ["rigid transform", "transformation matrix"], plain: "A matrix combining rotation and translation between coordinate frames.", technical: "A 4×4 SE(3) transform composes frame changes by matrix multiplication; order and direction are essential.", formula: "T = [[R,p],[0,1]]", example: "T_world_body T_body_camera maps camera coordinates into the world convention.", misconception: "Transform multiplication is not commutative, so reversing order changes meaning.", sources: [MODERN_ROBOTICS] },
  { id: "localization", term: "Localization", aliases: ["pose estimation"], plain: "Estimating where a robot is within a map or reference frame.", technical: "Localization combines motion and observation models with uncertainty; observability, data association, and map quality bound performance.", example: "Wheel odometry predicts pose while landmarks correct accumulated drift.", misconception: "A plotted pose is an estimate, not direct knowledge of true position.", sources: [MODERN_ROBOTICS] },
  { id: "odometry", term: "Odometry", aliases: ["dead reckoning"], plain: "Estimating motion by accumulating incremental measurements from the robot.", technical: "Wheel or inertial increments integrate into pose and therefore accumulate scale, bias, slip, timing, and geometry errors.", example: "Encoder counts estimate each wheel's travel between updates.", misconception: "High encoder resolution does not prevent pose drift from wheel slip.", sources: [MODERN_ROBOTICS] },
  { id: "encoder", term: "Encoder", aliases: ["shaft encoder", "position encoder"], plain: "A sensor producing counts or codes related to mechanical position or motion.", technical: "Resolution, edge decoding, index, missed counts, mounting, direction, and calibration determine usable information.", example: "A quadrature encoder reports wheel direction and count change.", misconception: "Encoder counts measure shaft motion, not guaranteed ground travel.", sources: [MODERN_ROBOTICS] },
  { id: "differential-drive", term: "Differential drive", aliases: ["two-wheel differential drive"], plain: "A mobile base steered by commanding left and right wheel speeds independently.", technical: "Center speed is the mean wheel speed and yaw rate is their difference divided by track width under no-slip planar assumptions.", formula: "v=(vR+vL)/2; ω=(vR−vL)/b", example: "Equal wheel speeds drive straight; opposite speeds rotate approximately in place.", misconception: "The kinematic model does not include slip, caster effects, or motor mismatch automatically.", sources: [MODERN_ROBOTICS] },
  { id: "pose-drift", term: "Pose drift", aliases: ["odometry drift"], plain: "Growing pose error caused by accumulating imperfect motion estimates.", technical: "Heading error couples into position and often grows faster than simple distance-scale error without absolute corrections.", example: "A small track-width calibration error bends an odometry path away from a straight reference.", misconception: "Resetting coordinates hides accumulated error but does not fix its cause.", sources: [MODERN_ROBOTICS] },
  { id: "track-width", term: "Track width", aliases: ["wheel separation", "axle track"], plain: "The effective lateral distance between left and right wheel contact paths.", technical: "Differential-drive yaw estimation uses effective track width, which may differ from a ruler measurement because of compliance and scrub.", units: "metre (m)", example: "A larger track width produces less yaw for the same left-right travel difference.", misconception: "Nominal wheel-center spacing is not always the best calibrated kinematic value.", sources: [MODERN_ROBOTICS] },
  { id: "perception", term: "Robot perception", aliases: ["environment perception"], plain: "Turning sensor data into task-relevant descriptions of the robot and its surroundings.", technical: "Perception includes calibration, preprocessing, feature extraction, inference, uncertainty, and evaluation against labeled conditions.", example: "Classify whether a tabletop region is occupied from range and image measurements.", misconception: "Sensor readings are not direct, complete copies of the world.", sources: [MODERN_ROBOTICS] },
  { id: "feature", term: "Feature", aliases: ["measured feature"], plain: "A selected measurable pattern used by an estimator or classifier.", technical: "Features may be engineered or learned and must be robust to nuisance variation while retaining task information.", example: "Edge orientation and brightness contrast can help locate a printed marker.", misconception: "A feature that separates one dataset may not generalize to new lighting or backgrounds.", sources: [MODERN_ROBOTICS] },
  { id: "recall", term: "Recall", aliases: ["sensitivity", "true-positive rate"], plain: "The fraction of actual positive cases that a detector finds.", technical: "Recall = TP/(TP+FN) and must be reported with class definition, threshold, and test distribution.", units: "dimensionless or percent", formula: "recall = TP/(TP+FN)", example: "Finding 90 of 100 actual obstacles gives 90% recall.", misconception: "High recall can coexist with many false alarms and therefore low precision.", sources: [MODERN_ROBOTICS] },
  { id: "confusion-matrix", term: "Confusion matrix", aliases: ["classification error matrix"], plain: "A table comparing predicted classes with actual reference classes.", technical: "Counts of true/false positives and negatives support class-specific metrics and expose imbalance hidden by accuracy.", example: "Obstacle predictions are tallied against labeled obstacle and clear cases.", misconception: "A confusion matrix is meaningful only with defined labels and representative evaluation data.", sources: [MODERN_ROBOTICS] },
  { id: "path-planning", term: "Path planning", aliases: ["motion planning"], plain: "Finding a route from start to goal that respects a model of obstacles and costs.", technical: "Planning searches configuration or state space; feasibility, optimality, dynamics, uncertainty, and replanning depend on the chosen abstraction.", example: "A grid planner routes around inflated furniture cells.", misconception: "A collision-free line in a map is not proof the physical robot can safely execute it.", sources: [MODERN_ROBOTICS] },
  { id: "cost-map", term: "Cost map", aliases: ["cost grid", "occupancy cost map"], plain: "A spatial representation assigning traversal penalty or prohibition to regions.", technical: "Costs encode obstacles, clearance, terrain, uncertainty, or preferences and strongly shape the planned route.", example: "Cells near walls receive higher cost than open floor cells.", misconception: "A cost value is a design encoding, not a direct physical measurement unless defined as one.", sources: [MODERN_ROBOTICS] },
  { id: "heuristic", term: "Search heuristic", aliases: ["cost-to-go estimate"], plain: "An estimate of remaining path cost used to guide a search.", technical: "An admissible heuristic never overestimates true remaining cost; consistency supports efficient A* graph search.", example: "Manhattan distance guides four-neighbor grid search without exceeding shortest path length.", misconception: "A more aggressive heuristic can be faster but may sacrifice optimality guarantees.", sources: [MODERN_ROBOTICS] },
  { id: "astar", term: "A* search", aliases: ["A-star"], plain: "A graph-search algorithm prioritizing traveled cost plus estimated remaining cost.", technical: "It expands nodes by f(n)=g(n)+h(n); completeness and optimality depend on graph and heuristic conditions.", formula: "f(n)=g(n)+h(n)", example: "A* finds a lowest-cost grid route with an admissible heuristic and nonnegative edge costs.", misconception: "A* does not itself model robot footprint, dynamics, or changing obstacles.", sources: [MODERN_ROBOTICS] },
  { id: "obstacle-inflation", term: "Obstacle inflation", aliases: ["configuration-space inflation"], plain: "Expanding map obstacles to account for robot size and desired clearance.", technical: "For a rigid footprint, inflation approximates a configuration-space obstacle via the footprint shape and chosen safety margin.", example: "A corridor disappears from the cost map if it is narrower than the inflated robot diameter.", misconception: "Inflation is not evidence of localization accuracy or a substitute for sensing and stopping margin.", sources: [MODERN_ROBOTICS] },
  { id: "replanning", term: "Replanning", aliases: ["online replanning"], plain: "Computing a new route when the map, goal, state, or execution evidence changes.", technical: "Triggers balance responsiveness against computation and route thrashing; the robot needs a safe behavior while a new plan is unavailable.", example: "A newly detected chair blocks the route and triggers a plan from current pose.", misconception: "Continuous replanning cannot make stale sensing or unsafe stopping distance harmless.", sources: [MODERN_ROBOTICS] },
  { id: "interface-contract", term: "Interface contract", aliases: ["integration contract"], plain: "A testable agreement describing what connected components provide and require.", technical: "It covers electrical, data, timing, units, frames, mechanical datums, startup, versioning, and fault response.", example: "A sensor contract states volts, pinout, message schema, hertz, timeout, and invalid flag.", misconception: "A type signature alone is not a full cyber-physical interface contract.", sources: [MIT_DESIGN] },
  { id: "latency-budget", term: "Latency budget", aliases: ["timing budget"], plain: "An allocation of allowable delay across stages of an end-to-end response.", technical: "Sensing, transport, queues, computation, scheduling, and actuation contributions combine, including jitter and worst credible cases.", units: "seconds (s)", example: "A 150 ms stop requirement might allocate 50 ms sensing, 50 ms communication, and 50 ms actuation.", misconception: "Average stage delays do not prove the end-to-end deadline is always met.", sources: [CONTROL_TUTORIALS] },
  { id: "heartbeat", term: "Heartbeat", aliases: ["liveness message"], plain: "A periodic indication that a component is still communicating or making specified progress.", technical: "Heartbeat period, sequence, payload, timeout, and independence determine which failures it can reveal.", example: "A controller emits a counter every 100 ms; missing several entries triggers degraded mode.", misconception: "A heartbeat proves only its defined liveness condition, not correct sensing or actuation.", sources: [ARDUINO_TIMING] },
  { id: "acceptance-test", term: "Acceptance test", aliases: ["acceptance check"], plain: "A test with predefined pass criteria deciding whether a requirement is met for a stated configuration.", technical: "The procedure records setup, revision, instruments, conditions, actual results, deviations, and evidence linked to the requirement.", example: "Five restrained-wheel command-loss trials must each stop output within 150 ms.", misconception: "Passing one acceptance condition is not general product certification.", sources: [MIT_DESIGN] },
  { id: "reliability", term: "Reliability", aliases: ["mission reliability"], plain: "Probability that a system performs its required function for a stated time under stated conditions.", technical: "Reliability needs a defined success event, population or model, duration, environment, and dependence assumptions.", units: "probability from 0 to 1", formula: "R_series = ∏Rᵢ for independent required elements", example: "Independent 0.99 elements in series yield 0.9801 reliability.", misconception: "Reliability is not the same as safety or availability.", sources: [MIT_DESIGN] },
  { id: "fault", term: "Fault", aliases: ["fault cause"], plain: "A defect or abnormal condition that can lead to an incorrect internal state.", technical: "Faults may be transient, intermittent, permanent, design, manufacturing, environmental, or operational and require defined detection scope.", example: "A loose encoder connector is a fault that may freeze counts.", misconception: "A fault is the cause, not necessarily the externally observed failure.", sources: [MIT_DESIGN] },
  { id: "error-state", term: "Error state", aliases: ["internal error"], plain: "An incorrect internal system condition caused by a fault.", technical: "An error may remain latent, be detected and contained, or propagate across interfaces until service fails.", example: "A frozen wheel-count value is an error state caused by a disconnected encoder.", misconception: "This reliability meaning differs from a control error signal or software error message.", sources: [MIT_DESIGN] },
  { id: "failure", term: "Failure", aliases: ["service failure"], plain: "A system's delivered service departing from its required behavior.", technical: "Failure is observed at a defined system boundary and can result from one or more propagated faults and errors.", example: "Driving the wrong distance is a failure after stale odometry affects control.", misconception: "A component fault does not always produce system failure if it is detected and contained.", sources: [MIT_DESIGN] },
  { id: "common-cause", term: "Common-cause failure", aliases: ["common-mode failure"], plain: "One shared cause defeating multiple supposedly redundant channels.", technical: "Shared power, environment, connector, calibration, software, or design assumptions invalidate naive independence calculations.", example: "Two range sensors both fail on the same glossy surface.", misconception: "Duplicating identical components does not eliminate shared vulnerabilities.", sources: [MIT_DESIGN] },
  { id: "degraded-mode", term: "Degraded mode", aliases: ["graceful degradation"], plain: "A deliberate reduced-capability operating state used after a fault or loss of confidence.", technical: "It specifies retained functions, tighter limits, annunciation, evidence, entry conditions, and recovery or shutdown criteria.", example: "A robot slows and uses encoders briefly after camera loss, then stops if uncertainty grows too large.", misconception: "Continuing normally while ignoring a failed input is not a defined degraded mode.", sources: [MIT_DESIGN] },
  { id: "decision-record", term: "Decision record", aliases: ["engineering decision record"], plain: "A short durable account of a choice, alternatives, evidence, and consequences.", technical: "It captures context, status, assumptions, selected option, rejected alternatives, revision, and links to calculations or tests.", example: "Record why a 330 Ω LED resistor was chosen and how current was verified.", misconception: "A final value without rationale or conditions is not a useful decision record.", sources: [MISSING_SEMESTER] },
  { id: "test-condition", term: "Test condition", aliases: ["test setup condition"], plain: "A documented environmental, hardware, software, load, and procedural circumstance under which evidence was collected.", technical: "Conditions bound applicability and include versions, instruments, calibration, timing, configuration, and deviations.", example: "Watchdog timing was measured with restrained wheels, named firmware, load, and clock method.", misconception: "A result cannot be generalized safely when its conditions are missing.", sources: [MIT_DESIGN] },
  { id: "observed-range", term: "Observed range", aliases: ["sample range"], plain: "The interval from the smallest to largest value actually observed in a dataset.", technical: "Range summarizes extremes in the sample but is sensitive to sample count and is not a guaranteed population bound.", units: "same as observation", formula: "range = max − min", example: "Five times from 108 to 115 ms have an observed range width of 7 ms.", misconception: "Observed minimum and maximum are not absolute future limits.", sources: [MIT_DESIGN] },
  { id: "provenance", term: "Provenance", aliases: ["data lineage", "source history"], plain: "A record of where an artifact or claim came from and how it changed.", technical: "Provenance links source identity, version, transformations, authorship, timestamps, licenses, and raw evidence to derived outputs.", example: "A plot cites the raw log, script revision, test setup, and processing parameters.", misconception: "A copied value with a URL but no version or transformation history has weak provenance.", sources: [MISSING_SEMESTER] },
];

const allModules = [
  ...foundationsElectronicsModules,
  ...mechanicsControlModules,
  ...embeddedRoboticsModules,
];

const relatedModulesByGlossaryId = new Map<string, string[]>();
for (const module of allModules) {
  for (const glossaryId of module.glossary) {
    const related = relatedModulesByGlossaryId.get(glossaryId) ?? [];
    related.push(module.id);
    relatedModulesByGlossaryId.set(glossaryId, related);
  }
}

export const advancedGlossary: GlossaryEntry[] = authoredGlossary.map(entry => ({
  ...entry,
  relatedModules: relatedModulesByGlossaryId.get(entry.id) ?? [],
}));
